(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-stream-batch-scheduler"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-1\">一 · 事故：一次晚高峰的语音客服雪崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-2\">二 · 它解决什么：chunk 粒度上的连续批处理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-3\">三 · 它不解决什么：边界之外的四个盲区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-4\">四 · 适用边界的判定：三个必要条件与一个规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-5\">五 · 与静态批的代价对照：一张必须算清的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-6\">六 · 稳定性技巧与失败模式的工程读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-7\">七 · 它救不了的那一类故障：状态碎片与抢占抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-8\">八 · 入队与优先级打分：把 SLO 折成可比较的数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-9\">九 · 组批与长度对齐：chunk 是唯一合法的拼接口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-10\">十 · 批量前向与状态寻址：每请求独立 KV 与卷积状态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-11\">十一 · 输出路由与流式回写：按请求拆批，按流控节流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-12\">十二 · 完成回收与新请求插槽：空槽是调度器的稀缺资源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-13\">十三 · 监控回环与抢占重算：调参的闭环与它的账单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-14\">十四 · 调度步的边界：抢占重算、状态碎片与对齐浪费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-15\">十五 · 目标函数：把 SLO 与 RTF 写成同一张约束表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-16\">十六 · 优先级公式：$\\alpha$ 与 $\\beta$ 各自在买什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-17\">十七 · 批内对齐：$\\epsilon$ 从哪里来，怎么压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-18\">十八 · 伪代码：一步调度的可实现形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-19\">十九 · 动态调参：监控量到控制量的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-20\">二十 · 边界条件与失效模式：RTF 约束下的调度代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-21\">二十一 · 负载配方的三个坐标：形态、长度分布、并发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-22\">二十二 · 长度分布决定对齐浪费与状态碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-23\">二十三 · 并发与批大小：上限由状态缓存而非算力决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-24\">二十四 · 负载不对时的三种失败形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-25\">二十五 · 配方标定的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-26\">二十六 · 负载配方与失效边界：什么时候这套调度器会反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-27\">二十七 · 硬件档位的选型判据：从 RTF 余量反推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-28\">二十八 · 并行拓扑：状态归属决定切分方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-29\">二十九 · 量化方案：调度层不碰数值格式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-30\">三十 · KV 与卷积状态策略：分池、对齐与回收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-31\">三十一 · 调度参数：优先级权重与动态上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-32\">三十二 · 可复现配置思路与稳定性锁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-33\">三十三 · 配方落地后的边界：状态碎片、抢占重算与 chunk 双刃</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-34\">三十四 · 显存：碎片先于容量见底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-35\">三十五 · 带宽：对齐填充与状态读写的双重税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-36\">三十六 · 通信：状态分池跨卡后的隐性同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-37\">三十七 · 功耗与热：持续高占用的隐性上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-38\">三十八 · 尾延迟：抢占重算与长请求饿死的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-39\">三十九 · 规模上去以后先崩的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-40\">四十 · 规模上去以后，先崩的是状态池而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-41\">四十一 · 精度漂移：从数值格式到可观测指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-42\">四十二 · OOM 与碎片：状态池的生命周期账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-43\">四十三 · 批抖动与路由不均：抢占的连锁反应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-44\">四十四 · 尾延迟尖刺：三个来源的分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-45\">四十五 · 监控面与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-46\">四十六 · 工程判断：失败模式决定参数标定顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-47\">四十七 · 过载边界：抢占重算、状态碎片与对齐浪费的三角</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-48\">四十八 · 同族算法谱系与选择维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-49\">四十九 · 决策表：按负载形态选族内成员</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-50\">五十 · 与相邻流式解码算法的接口选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-51\">五十一 · 与分离式预填/解码及并行通信的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-52\">五十二 · 适用条件与不适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stream-batch-scheduler-sec-53\">五十三 · 同族调度器的分岔口：何时该用 chunk 级连续批处理，何时该退回去</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:527px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 527.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入队列，按首包 SLO 与已服务 chunk 数计算优先级</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器每步选取若干请求的当前 chunk 组成 batch，填充到对齐长度</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批量前向计算声学/编解码 chunk，输出按请求路由回各自流</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">完成的请求释放 KV/状态缓存，新请求插入空出的 batch 槽位</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">监控首包延迟与 RTF，动态调整 batch 上限与 chunk 大小</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-stream-batch-scheduler-sec-1\">一 · 事故：一次晚高峰的语音客服雪崩</h3>\n<p>某在线语音客服系统在晚高峰遭遇了一次典型的推理事故：P99 首包延迟从常态的数百毫秒级跳到数秒级，同时 GPU 利用率不升反降。排查发现根因不在模型也不在数值精度，而在批处理策略本身。该系统采用静态批处理：调度器攒够固定数量的请求后一次性组批、一次前向、等整批最慢的请求结束后再收下一批。语音请求的音频长度方差极大——问候语两三秒，投诉录音几十秒——静态批的完成时间由批内最长请求决定，短请求被迫陪跑。更糟的是，一个长请求占住 batch 槽位期间，新到达的短请求只能在队列里干等，首包 SLO 被同批长请求直接拖垮。运维侧的应对是加大 batch 上限以提升吞吐，结果对齐填充的算力浪费和状态缓存膨胀进一步压低了有效吞吐，形成“越调越慢”的正反馈。</p>\n<p>这个事故暴露的不是某个算子的性能问题，而是调度粒度与请求长度分布不匹配的结构性缺陷。流式 TTS 与语音对话服务的负载特征是：请求到达时间随机、音频长度重尾分布、首包延迟是硬约束、长请求追求实时率。静态批处理把“批”当成不可分割的调度单元，等于把最长请求的完成时间强加给批内所有请求，首包延迟与吞吐被绑死在同一条曲线上，无法解耦。流式多模态批调度要解决的正是这个耦合。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-2\">二 · 它解决什么：chunk 粒度上的连续批处理</h3>\n<p>该调度器的核心动作是把调度粒度从“请求”下沉到“chunk”。一个流式请求被切分为若干音频 chunk，每个 chunk 对应一次前向计算；调度器每一步不等待整批请求完成，而是选取当前活跃请求各自的“当前 chunk”拼成一个 batch，对齐长度后做一次批量前向，输出按请求路由回各自的输出流。请求完成后释放其 KV 与卷积状态，空出的 batch 槽位立刻被新请求填入。这样 GPU 在时间轴上几乎不留空转，而新请求的首包不必等待任何长请求结束——它只需要等到下一个调度步。</p>\n<p>调度决策由优先级驱动。给定请求 $r$ 的首包延迟约束 $\\mathrm{SLO}_r$ 与已服务 chunk 数 $n^{\\mathrm{served}}_r$，优先级可形式化为</p>\n<div class=\"formula\">$$p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$$</div>\n<p>其中 $\\alpha,\\beta$ 为权重。第一项让首包 SLO 紧的请求优先进入 batch，第二项让已经服务较多 chunk 的长请求获得推进惯性，避免被无限期插队。过载时调度器按 $p_r$ 决定抢占与增删：牺牲长尾吞吐、保住首包硬约束。这与静态批“一次成型、等最慢请求”的差别在于增删时机——本方法每一步都可增删请求，首包延迟不再被同批长请求污染。</p>\n<p>系统代价必须算清楚。chunk 级调度换来的是利用率与延迟解耦，付出的是状态管理与对齐开销：每个请求持有独立的 KV cache 与卷积状态，batch 内长度对齐到 chunk 边界仍会浪费部分算力；优先级抢占导致已分配的 chunk 需要重算，尾延迟抖动被放大。以一个混合长度负载为例：短问候请求与长投诉录音同批，静态批下短请求首包要等长请求整段合成完毕；chunk 级连续批下短请求在下一个调度步即可插入空槽，其首包延迟只取决于单 chunk 前向时间与排队位置，而长请求按自己的节奏逐 chunk 推进，互不阻塞。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-3\">三 · 它不解决什么：边界之外的四个盲区</h3>\n<p>第一，它不改变数值精度栈。调度层沿用模型既有的量化格式，NVFP4/FP8 的算子选择、tcgen05 与 TMEM 的排布、2-SM MMA 的配对策略都在算子层决定，调度器只决定“哪些 chunk 拼在一起、何时拼”，不决定“用什么精度算”。把首包延迟问题寄希望于调度器降精度是错配。</p>\n<p>第二，它不解决单请求内部的实时率瓶颈。若某请求的 chunk 计算本身慢于音频播放速度，即 $\\text{RTF}&gt;1$，再怎么调度也无法让它跟上实时流；调度器能做的是在 $\\text{RTF}\\le 1$ 的约束下最大化满足 SLO 的请求数：</p>\n<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>\n<p>第三，它不解决显存碎片的结构性上限。每请求独立卷积与 KV 状态带来碎片，长对话下碎片累积会触发 OOM 或强制驱逐，吞吐骤降。调度器可以用分池分配与生命周期回收缓解，但碎片率的上界由状态缓存容量决定，batch 规模存在硬天花板，超过后对齐浪费与抢占重算会推高尾延迟抖动。第四，它不解决跨节点通信与并行策略问题——NVLink 5 域内的张量并行切分、NCCL 集合通信、分离式预填/解码的节点间传输，都是调度层之外的独立议题，调度器只在其上做请求级编排。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-4\">四 · 适用边界的判定：三个必要条件与一个规模上限</h3>\n<p>判定一个服务是否该用这套调度，看三个必要条件是否同时成立。其一，请求长度方差大：若所有请求音频长度接近，静态批的“等最慢”代价可忽略，chunk 级调度的状态开销反而得不偿失。其二，首包 SLO 严格且为硬约束：若首包延迟只是软目标，静态批加适当超时即可。其三，在线到达而非离线批处理：离线场景可以按长度排序组批，连续批处理的增删灵活性没有价值。</p>\n<p>规模上限由两个量共同约束：状态缓存容量决定同时在途请求数的上界，显存碎片率决定该上界随对话时长衰减的速度。工程上的判据是——当 batch 上限提升带来的吞吐增益被对齐浪费与抢占重算的尾延迟抖动抵消时，即到达拐点。此时应联合调参 chunk 大小：chunk 过大则首包延迟上升（首包必须等一个完整 chunk 算完），chunk 过小则调度与状态切换开销占比过高。负载配方上，短请求追求首包、长请求追求实时率，两级 SLO 的设计正是为了在过载时明确取舍顺序：保首包、牺牲长尾。</p>\n<p>一个具体的边界案例：单卡多流部署下，若在途请求数逼近状态缓存容量，碎片累积使新请求无法分配状态，调度器被迫驱逐长请求；长请求被驱逐后其已服务 chunk 作废，重进队列时 $n^{\\mathrm{served}}_r$ 归零、优先级下降，在持续过载下可能被反复饿死。这不是调度逻辑的 bug，而是容量边界被触碰后的必然行为，说明该算法的适用规模受显存碎片与状态缓存容量硬约束，扩容或分池才是解法，调调度参数无效。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-5\">五 · 与静态批的代价对照：一张必须算清的账</h3>\n<p>把两种策略在同一混合长度负载下的代价拆开看，差异集中在三处。调度粒度：静态批以请求为单元，完成时间取批内最大值；chunk 级以 chunk 为单元，完成时间逐请求独立。增删时机：静态批一次成型、中途不可变；chunk 级每步可增删，新请求插入空槽。状态管理：静态批状态随批分配、批结束统一释放，碎片少但槽位利用率低；chunk 级状态按请求生命周期独立分配回收，槽位利用率高但碎片累积。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>静态批处理</th><th>chunk 级连续批处理</th></tr></thead><tbody><tr><td>首包延迟决定因素</td><td>批内最长请求</td><td>单 chunk 前向时间 + 排队位置</td></tr><tr><td>GPU 空转来源</td><td>攒批等待、等最慢请求</td><td>对齐填充、状态切换</td></tr><tr><td>过载取舍</td><td>无优先级，全体劣化</td><td>按 $p_r$ 保首包、牺牲长尾</td></tr><tr><td>主要风险</td><td>短请求陪跑、吞吐塌陷</td><td>显存碎片、抢占重算抖动</td></tr></tbody></table>\n<p>这张表的工程含义是：静态批在长度方差小的负载上更省心，chunk 级调度在长度方差大且首包硬约束的负载上才划算。事故案例中的系统恰属后者，却用了前者的策略，失败是结构性的而非参数性的。值得注意的是，chunk 级调度并未消除所有等待——对齐填充仍浪费算力，抢占重算仍放大尾延迟，只是把这些代价从“首包延迟”转移到了“长尾吞吐”，而两级 SLO 的设计正是承认这种转移并主动选择它。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-6\">六 · 稳定性技巧与失败模式的工程读法</h3>\n<p>三个稳定性技巧对应三个失败模式，读法要落到具体机制上。限制单 batch 请求数与 chunk 上限，针对的是长请求饿死短请求：若无上限，长请求凭 $n^{\\mathrm{served}}_r$ 项持续占据槽位，短请求的 $1/\\mathrm{SLO}_r$ 项再大也排不进 batch。对抢占导致的已分配 chunk 做重算补偿，针对的是尾延迟抖动：被抢占的 chunk 不能简单丢弃，需记录其计算进度并在重新调度时优先补算，否则长请求的 RTF 会被反复打断推高。状态分池分配与按请求生命周期回收，针对的是显存碎片：把 KV 与卷积状态按尺寸分池，避免长短请求的状态交错分配造成不可用空洞。</p>\n<p>监控闭环是这套调度能稳住的前提：首包延迟与 RTF 两个指标驱动 batch 上限与 chunk 大小的动态调整。首包延迟逼近 SLO 时收缩 batch 上限、减小 chunk，让新请求更快插入；RTF 逼近 1 时反向操作，增大 chunk 摊薄调度开销。这个闭环的稳定性取决于两个时间尺度的分离——调度步是毫秒级，参数调整是秒级，若两者混在同一尺度上会引发振荡。工程判断上，chunk 级连续批处理不是“更快的批处理”，而是把延迟与吞吐从同一条曲线上拆开、再用优先级把两者重新绑到 SLO 上的调度重构；它的收益上限由负载长度方差决定，成本下限由状态缓存容量决定，两者共同划定了这套算法值得部署的区间。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-7\">七 · 它救不了的那一类故障：状态碎片与抢占抖动</h3>\n<p>这套 chunk 级连续批处理能解的是“到达时间散、音频长短悬殊”造成的静态批错配：静态批一次成型、等最慢请求，长请求把短请求的首包一起拖住，GPU 又在等待期空转。但它不解决显存管理本身。每个请求的卷积状态与 KV 独立分池，长对话下碎片累积，最终触发 OOM 或强制驱逐，吞吐骤降——这是调度层无法用拼批消除的失效条件。调度器能做的是限制单 batch 请求数与 chunk 上限，并按请求生命周期回收状态，但它无法把碎片整理成连续块；规模上限因此由状态缓存容量而非算力决定。</p>\n<p>第二类失效来自优先级机制自身。过载时按 <span class=\"formula\">$$p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$$</span> 抢占，被踢出的请求已分配的 chunk 必须重算，尾延迟抖动被放大；持续过载下长请求可能被饿死。约束 <span class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</span> 说明保首包与保实时率是两套目标：过载时只能牺牲长尾吞吐换硬约束，这是策略选择，不是算法缺陷。</p>\n<p>第三类是粒度代价。批内长度对齐到 chunk 边界仍浪费算力；chunk 过大首包延迟上升，chunk 过小则调度与状态切换开销占比过高。适用边界因此明确：请求长度方差大、首包 SLO 严格的在线服务收益最大；请求长度均匀或 SLO 宽松时，静态批的简单性反而更省。下表给出边界判断。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>适用</th><th>不适用/退化</th></tr></thead><tbody><tr><td>长度方差</td><td>大，混合长短请求</td><td>均匀，静态批足够</td></tr><tr><td>首包 SLO</td><td>硬约束、严格</td><td>宽松，吞吐优先</td></tr><tr><td>状态容量</td><td>碎片可控、可回收</td><td>长对话累积触发 OOM</td></tr><tr><td>过载程度</td><td>短时尖峰，可抢占</td><td>持续过载，长请求饿死</td></tr></tbody></table>\n<h3 id=\"alg-stream-batch-scheduler-sec-8\">八 · 入队与优先级打分：把 SLO 折成可比较的数</h3>\n<p>请求进入调度器时并不直接进 batch，而是先落在一个按优先级排序的等待队列里。入队动作的输入是请求元数据：首包延迟约束 <span class=\"inline-math\">SLO<sub>r</sub></span>、预估音频总长、编解码器类型、采样率与码本层数、以及该请求是否属于长对话（决定 KV 与卷积状态池的分配档位）。输出是一个带优先级标量的队列节点，代价是一次常数级打分与一次堆插入，属于微秒级操作，不占 GPU 时间，但队列深度本身是显存之外的另一种容量约束——队列过长意味着准入控制失效。</p>\n<p>打分用的事实是两条：首包还剩多少余量，以及这个请求已经被服务了多少 chunk。前者决定“急不急”，后者决定“欠了多少债”。写成式子就是</p>\n<div class=\"formula\">$$p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$$</div>\n<p>其中 <span class=\"inline-math\">n<sup>served</sup><sub>r</sub></span> 是已服务 chunk 数。这个式子的工程含义是：短 SLO 请求天然拿到更高基础分，而随着 chunk 被逐步消耗，长请求的分数单调上升，从而不会在持续过载下被无限饿死。权重 <span class=\"inline-math\">α、β</span> 的比值实际上就是“保首包”与“保长尾”之间的旋钮，过载时把 <span class=\"inline-math\">α</span> 抬上去，等价于承认长尾吞吐是软目标。代价是打分本身无法感知真实剩余时间，只能靠监控回环修正，所以队列节点必须携带上一次实测的首包延迟残差，供调度器在下一步做补偿。</p>\n<p>具体例子：三个请求同时到达，SLO 分别为 200 ms、600 ms、1.5 s，已服务 chunk 数均为 0。按上式，第一个请求分数最高，会优先被选入下一步的 batch；当它服务到第 4 个 chunk 仍未出首包时，监控层会把它标记为“首包风险”，并在下一步强制提升其优先级，即使这意味着要从别的请求那里抢一个槽位。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-9\">九 · 组批与长度对齐：chunk 是唯一合法的拼接口径</h3>\n<p>调度器每步从队列头部取出若干请求，各取“当前待算的那一个 chunk”，拼成一个 batch。输入是每个请求的 chunk 索引、该 chunk 的 token 数或帧数、以及状态池句柄；输出是一个对齐后的批张量加上一张路由表（batch 内第几行属于哪个请求的第几个 chunk）。这一步的代价不在计算而在对齐：批内所有序列必须填充到同一长度，填充部分照样走前向，白烧算力。对齐到 chunk 边界而不是 token 边界，是为了让填充浪费有上界——最坏情况是批内最长 chunk 与最短 chunk 之差，而不是整段音频长度之差。</p>\n<p>伪代码层面的组批逻辑可以写成：按优先级遍历队列，累计已选 chunk 的帧数，一旦超过 batch 上限或显存预算就停止；然后取批内最大帧数 <span class=\"inline-math\">L<sub>max</sub></span>，把所有 chunk 右侧补到 <span class=\"inline-math\">L<sub>max</sub></span>，同时记录每行的有效长度供注意力掩码使用。填充率 <span class=\"inline-math\">ρ = ΣL<sub>i</sub> / (N·L<sub>max</sub>)</span> 是这一步唯一值得盯的指标：<span class=\"inline-math\">ρ</span> 低于某个阈值说明 chunk 大小选得不对，或者批内长度方差过大，应该拆批而不是硬拼。</p>\n<p>代价的具体形态：假设批内 8 个请求，chunk 帧数分别为 40、40、40、40、40、40、40、160，则 <span class=\"inline-math\">L<sub>max</sub>=160</span>，填充率只有约 0.31，七成算力烧在填充上。这不是理论担忧，而是混合长度流式请求的常态。工程判断是：当批内出现一个明显超长的 chunk 时，宁可把它单独成批或延后一步，也不要让它绑架其余七个请求的对齐长度——延后一步的代价是这一个请求的首包延迟增加一个 step time，而绑架的代价是整批的 RTF 恶化。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-10\">十 · 批量前向与状态寻址：每请求独立 KV 与卷积状态</h3>\n<p>批量前向的输入是对齐后的批张量、每请求的状态池句柄、以及模型既有精度栈下的权重（调度层不改数值格式，NVFP4/FP8 的选择在模型侧已经定死）。输出是每个请求当前 chunk 的声学特征或编解码 token。计算本身走的是标准的批矩阵乘与注意力，真正的机制难点在状态寻址：每个请求有独立的 KV cache 与卷积/循环状态，批内不同行指向不同池区，注意力掩码必须同时表达“填充位置不算”和“跨请求不互看”。</p>\n<p>这一步的代价分三块。算力代价随 <span class=\"inline-math\">N·L<sub>max</sub></span> 线性增长，填充直接计入。显存带宽代价随状态池的分散程度上升——批内 8 个请求指向 8 个不连续的 KV 区，访存局部性远差于单请求连续解码，这是连续批处理在带宽上的固有税。显存容量代价则是碎片：每个请求的状态按生命周期分配与回收，长短请求交错后池内出现大量不连续空洞，长对话累积下碎片率上升，最终触发 OOM 或强制驱逐。缓解手段是分池：把短请求与长对话请求放进不同尺寸的状态池，按档位分配，牺牲一点池利用率换碎片可控。</p>\n<p>具体例子：一个 8 路并发的语音对话服务，其中 2 路是长对话（已积累数千帧的 KV），6 路是短问答。若共用一个大池，短请求完成后留下的空洞无法被长请求利用；分池后，短池按 chunk 生命周期快速回收，长池按会话粒度增长，碎片被限制在各自池内。代价是长池的预留容量在低峰期闲置，这是用显存换稳定性的典型取舍。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-11\">十一 · 输出路由与流式回写：按请求拆批，按流控节流</h3>\n<p>前向完成后，输出张量要按路由表拆回各请求，写入各自的输出流缓冲。输入是批输出与路由表，输出是每请求一个 chunk 的音频帧或 token 序列，代价是一次按行切片加一次跨流拷贝，属于内存带宽操作而非算力操作。真正决定首包延迟的是这一步之后的流控：音频必须以不慢于实时的速率吐出，否则客户端缓冲会膨胀；但也不能一次性灌完，否则失去流式意义。</p>\n<p>回写节流的判据就是 RTF：</p>\n<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>\n<p>RTF 小于 1 意味着算得比播得快，缓冲会持续增长，此时应缩小 chunk 或降低 batch 上限以压低单步时间；RTF 逼近 1 意味着系统贴着实时线跑，任何一步的抖动都会变成可听见的断流。这一步的代价体现在延迟剖面上：路由与拷贝本身不慢，但它把“批内最慢请求”的时间传染给了所有请求——批前向必须等最慢那一行算完，输出才能拆批，于是首包延迟被同批长 chunk 拖累。这正是 chunk 级调度要解决的问题，也是为什么组批时要避免超长 chunk 绑架整批。</p>\n<p>具体例子：某步 batch 内 7 个短 chunk 在 3 ms 内算完，1 个长 chunk 需要 11 ms，则整批输出在 11 ms 后才拆批回写，7 个短请求的首包各多等 8 ms。若把这 1 个长 chunk 挪到下一步单独成批，7 个短请求的首包立刻回到 3 ms 量级，代价是长请求晚一步。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-12\">十二 · 完成回收与新请求插槽：空槽是调度器的稀缺资源</h3>\n<p>请求的最后一个 chunk 输出后，调度器释放其 KV 与卷积状态、归还池句柄、从活跃表中摘除，并在下一步把等待队列头部的新请求填入空出的 batch 槽位。输入是完成事件与空槽计数，输出是更新后的活跃请求集合。这一步的代价是状态回收的同步开销：池句柄归还必须等该请求的最后一次前向确实完成，否则会出现状态被复用时旧数据未清的情况；在单机多流部署下，这要求回收动作与下一步组批之间有明确的顺序约束，通常靠一个每步递增的 epoch 标记来保证。</p>\n<p>空槽插入的时机决定了首包延迟的下界。新请求插入后仍需至少一步前向来产生首包，所以首包延迟的下界约等于“排队等待步数 × 单步时间 + 一步前向时间”。缩短这个下界的办法不是加大 batch，而是提高槽位周转率：限制单 batch 请求数、限制 chunk 上限，让每个请求占槽时间可控。反过来，槽位周转过快会让调度与状态切换开销占比上升，chunk 过小时尤其明显——每步的固定开销被摊薄到很少的有效计算上。</p>\n<p>具体例子：单卡多流部署，batch 上限设为 12，chunk 上限设为 64 帧。一个 3 秒的短请求约需十余个 chunk，占槽时间有限；一个 60 秒的长对话请求则长期占槽。若不限制长请求的 chunk 上限，长请求会持续霸占槽位，新到的短请求只能在队列里等，首包 SLO 直接失守。限制 chunk 上限等价于强制长请求周期性让出计算窗口，代价是长请求的 RTF 略微变差，但换来了短请求的首包可达性。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-13\">十三 · 监控回环与抢占重算：调参的闭环与它的账单</h3>\n<p>每一步结束后，监控层收集两个实测值：各请求的首包延迟残差，以及整批的 RTF。这两个值回灌给调度器，驱动三个动作：调整 batch 上限、调整 chunk 大小、触发优先级抢占。batch 上限与 chunk 大小是一对耦合参数——batch 过大时对齐浪费与抢占重算推高尾延迟抖动，chunk 过大时首包延迟上升，chunk 过小时调度与状态切换开销占比过高。调参的正确姿势是先把 chunk 定在让单步时间稳定的档位，再在 RTF 有余量时逐步抬 batch 上限，而不是反过来。</p>\n<p>抢占是过载时的最后手段：当某请求的首包风险超过阈值，调度器从低优先级请求那里收回已分配的槽位，把算力让给它。代价是账单明确——被抢占请求已经算过的那个 chunk 作废，必须重算，尾延迟抖动因此放大；若过载持续，被反复抢占的长请求可能长期得不到推进，形成事实上的饿死。补偿手段是对被抢占的 chunk 做重算记账，在优先级公式里给它的 <span class=\"inline-math\">n<sup>served</sup></span> 加一个补偿项，让它在下一轮拿到更高分数。这个补偿项不能太大，否则抢占失去意义；也不能太小，否则长请求在过载下永远排在后面。</p>\n<p>工程判断落在最后这一步：调度器的稳定性不取决于单步决策多聪明，而取决于监控回环的采样周期是否短于 SLO 的量级。若首包 SLO 是百毫秒级，而监控每步只更新一次、每步时间又是十毫秒级，回环有足够的带宽去纠正偏差；若 chunk 大到单步时间接近 SLO，回环就失去纠正能力，任何一次误判都直接变成违约。因此 chunk 大小的选择本质上是在给监控回环留带宽，而不是单纯在优化 RTF。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-14\">十四 · 调度步的边界：抢占重算、状态碎片与对齐浪费</h3>\n<p>这套 chunk 级连续批处理在每一步都要做三件事：按优先级选请求、把各自的当前 chunk 对齐成一批、前向之后按请求路由输出。边界恰恰出在“选”和“对齐”之间。优先级式 $p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$ 在过载时决定谁被挤出 batch 槽位，但被挤出的请求已经算过的 chunk 不会自动作废——若它随后被重新插入，这部分 chunk 必须重算，尾延迟抖动由此放大。长请求在持续过载下 $n^{\\mathrm{served}}_r$ 虽在增长，却可能长期拿不到槽位而被饿死。工程上必须给抢占设上限：单 batch 请求数与 chunk 上限同时约束，重算补偿只对最近一个已分配 chunk 生效，而不是回滚整条流。</p>\n<p>对齐浪费是可量化的系统代价。设 batch 内各请求当前 chunk 长度为 $l_i$，对齐到 chunk 边界后的填充比例为 $\\frac{\\max_i l_i \\cdot B - \\sum_i l_i}{\\max_i l_i \\cdot B}$，它直接吃掉 MMA 的有效算力；chunk 越大，首包延迟越高，chunk 越小，调度与状态切换开销占比越高。更隐蔽的是状态侧：每请求独立的卷积状态与 KV 分池分配，生命周期长短不一，长对话下碎片累积会触发 OOM 或强制驱逐，吞吐骤降。这与静态批一次成型、等最慢请求的差别不在算法，而在状态管理与对齐开销被搬到了每一步。</p>\n<p>因此适用边界很窄：请求长度方差大、首包 SLO 为硬约束、长尾吞吐为软目标的在线服务才值得付这份代价。监控量是首包延迟与 RTF，约束为 $\\text{RTF} = T_{\\text{compute}}^{\\text{batch}} / T_{\\text{audio}}^{\\text{batch}} \\le 1$ 且 $\\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i]$；一旦 RTF 逼近 1，说明对齐与重算已把算力吃满，此时应缩 batch 上限而非加 chunk。规模上限由显存碎片与状态缓存容量决定，调度层不改变数值格式，量化沿用模型既有精度栈，所以碎片问题只能靠分池与生命周期回收解决，不能指望精度侧腾空间。</p>\n<h3 id=\"alg-stream-batch-scheduler-sec-15\">十五 · 目标函数：把 SLO 与 RTF 写成同一张约束表</h3>\n<p>调度器要解的不是一个纯吞吐问题，而是一个带硬约束的混合整数选择问题。给定请求集合 $\\mathcal{R}$，第 $i$ 个请求的首包延迟 $L_{\\text{first},i}$ 必须落在其 $\\text{SLO}_i$ 之内，同时整批的实时率不得越界：</p>\n<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>\n<p>逐项拆开看。$T_{\\text{compute}}^{\\text{batch}}$ 是这一调度步内批量前向的墙钟时间，包含对齐填充后的无效算力、状态换入换出、以及被抢占 chunk 的重算；$T_{\\text{audio}}^{\\text{batch}}$ 是这批 chunk 对应的音频时长之和，等于 $\\sum_i c_i \\cdot \\tau$，其中 $c_i$ 是请求 $i$ 本步贡献的 chunk 数、$\\tau$ 是单 chunk 音频时长。RTF ≤ 1 的含义是“算得比播得快”，它是流式服务的物理下限：一旦 RTF 越过 1，播放缓冲必然耗尽，任何首包优化都失去意义。目标函数用指示函数求和，而不是对延迟取平均，是因为首包 SLO 是硬约束——平均延迟再漂亮，只要有个别请求破线，用户体验就是断的。这就决定了调度必须是“计数式”的：最大化达标请求个数，而非最小化总延迟。</p>\n<p>关键推导一步在于把 RTF 约束转成 batch 规模的上界。设单请求单 chunk 的计算代价为 $w$（与模型、精度栈、chunk 大小绑定），batch 内请求数为 $B$，则 $T_{\\text{compute}}^{\\text{batch}} \\approx B \\cdot w \\cdot (1+\\epsilon)$，$\\epsilon$ 是对齐填充与状态切换带来的放大系数；而 $T_{\\text{audio}}^{\\text{batch}} = B \\cdot \\tau$。两边相除，$B$ 被约掉：</p>\n<div class=\"formula\">$$\\text{RTF} \\approx \\frac{w(1+\\epsilon)}{\\tau} \\le 1 \\;\\Longrightarrow\\; \\tau \\ge w(1+\\epsilon)$$</div>\n<p>这个结果说明 RTF 约束本质上是 chunk 大小的下界，而不是 batch 大小的上界——batch 变大只等比放大分子分母，真正决定能否实时的，是“一个 chunk 的音频时长是否覆盖它的计算时间”。工程含义很直接：chunk 太小，$\\tau$ 撑不住 $w$，RTF 破 1；chunk 太大，首包延迟被拉长。batch 上限的作用是控制 $\\epsilon$ 与尾延迟抖动，不是控制 RTF 本身。举例：某流式 TTS 请求短句首包 SLO 紧、长对话请求追求实时率，调度器若把 chunk 定在能覆盖单 chunk 前向代价的水平，则长短请求可以同批共存而不互相拖累 RTF；反之把 chunk 压到极小去抢首包，分子里的固定开销占比上升，RTF 反而恶化。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-16\">十六 · 优先级公式：$\\alpha$ 与 $\\beta$ 各自在买什么</h3>\n<p>过载时必须有取舍，取舍靠优先级排序。给定公式：</p>\n<div class=\"formula\">$$p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$$</div>\n<p>第一项 $\\alpha/\\mathrm{SLO}_r$ 是“紧迫度”：SLO 越紧，优先级越高，保证硬约束请求先拿到 batch 槽位。第二项 $\\beta \\cdot n^{\\mathrm{served}}_r$ 是“服务进度补偿”：已服务 chunk 数越多，优先级越高，用来对抗长请求被持续饿死。两项的权重比决定了调度性格。$\\alpha$ 相对大，系统偏保守，过载时死保首包，长尾吞吐作为软目标被牺牲；$\\beta$ 相对大，系统偏公平，长请求能持续拿到槽位，但新到的紧 SLO 请求可能排队，首包达标计数下降。</p>\n<p>推导上要注意 $n^{\\mathrm{served}}_r$ 的量纲问题：它随请求生命周期单调增长，若不设上限，一个跑了很久的长请求会凭惯性压过所有新请求。可实现的处理是给第二项加饱和，例如用 $\\beta \\cdot \\min(n^{\\mathrm{served}}_r, N_{\\text{cap}})$，$N_{\\text{cap}}$ 与单 batch 请求数上限联动，防止长请求垄断。另一个推导要点是抢占判据：当新请求的 $p_r$ 超过当前 batch 中最小优先级请求时触发替换，被替换请求已分配的 chunk 需要重算，这笔重算代价必须计入 $T_{\\text{compute}}^{\\text{batch}}$ 的 $\\epsilon$，否则 RTF 估计会系统性偏乐观。代价侧：优先级计算本身是每步 $O(B)$ 的轻量操作，真正的开销在抢占引发的重算与状态换出——尾延迟抖动主要来源于此，而非排序本身。具体例子：两级 SLO 下，首包延迟为硬约束、长尾吞吐为软目标，过载时调度器按 $p_r$ 把紧 SLO 新请求插进空槽，长请求被降级但仍保留 $\\beta$ 项防止彻底饿死，这正是“保首包、牺牲长尾”的可执行形态。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-17\">十七 · 批内对齐：$\\epsilon$ 从哪里来，怎么压</h3>\n<p>batch 内各请求当前 chunk 的 token 数不同，前向要求张量形状一致，必须对齐到 chunk 边界。设请求 $i$ 本步 chunk 的 token 数为 $l_i$，对齐后长度为 $\\hat{l} = \\lceil \\max_i l_i / g \\rceil \\cdot g$，$g$ 为对齐粒度（与 chunk 边界绑定）。填充浪费率为：</p>\n<div class=\"formula\">$$\\text{waste} = 1 - \\frac{\\sum_i l_i}{B \\cdot \\hat{l}}$$</div>\n<p>这个式子给出两条工程判断。其一，浪费率随 batch 内长度方差上升，混合长度请求正是本调度器的目标负载，所以对齐浪费是结构性代价，不可能消掉，只能压。其二，把 $g$ 对齐到 chunk 边界而非 token 边界，可以让 $\\hat{l}$ 只取少数几个离散值，减少形状切换带来的 kernel 重编译与状态重排开销——这部分开销计入 $\\epsilon$ 的固定项，chunk 越小时它占比越高，这正是“chunk 过小则调度与状态切换开销占比过高”的量化来源。举例：一批请求里短请求 chunk 只有几十个 token、长请求 chunk 数百 token，若按 token 粒度对齐，$\\hat{l}$ 每步都在变；按 chunk 边界对齐后 $\\hat{l}$ 稳定，填充浪费虽在，但 kernel 启动与状态搬运的固定成本被摊薄。代价落到算力上：填充位置的 MMA 仍在跑，浪费率直接折算成有效吞吐损失；落到显存上，对齐后的激活张量按 $\\hat{l}$ 分配，是每步的瞬时峰值而非累积量。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-18\">十八 · 伪代码：一步调度的可实现形态</h3>\n<p>把上述公式落到每步循环，核心是“选请求—对齐—前向—路由—回收”五段，状态按请求独立管理并分池分配：</p>\n<ul>\n<li>队列侧：新请求入队，计算 $p_r$，与当前 batch 槽位比较；有空槽直接插入，无空槽则按抢占判据替换最小优先级请求，被替换者标记待重算。</li>\n<li>组批侧：取每个在批请求的当前 chunk，按 $g$ 对齐到 $\\hat{l}$，拼成形状统一的输入张量；同时按请求索引收集各自的 KV 与卷积状态句柄。</li>\n<li>前向侧：一次批量前向产出各请求的声学或编解码 chunk，输出按请求路由回各自流，写回播放缓冲。</li>\n<li>回收侧：请求完成则释放其 KV 与卷积状态回池；被抢占请求的已分配 chunk 进入重算队列，重算结果合并回原流。</li>\n<li>监控侧：每步记录首包延迟与 RTF，越界则下调 batch 上限或上调 chunk 大小；RTF 富余则反向调整以吃吞吐。</li>\n</ul>\n<p>伪代码层面的关键不变量是：状态句柄与请求一一绑定，batch 只是这些句柄的临时集合，任何增删都不迁移状态本身。这让新请求插入空槽成为 $O(1)$ 的指针操作，而不是状态重建。代价体现在显存上：每请求独立的卷积与 KV 状态按生命周期分配与回收，长对话下碎片累积，池化分配只能延缓而不能消除碎片，最终触发 OOM 或强制驱逐，吞吐骤降——这是该调度器最典型的失败模式，监控侧必须把状态池水位与碎片率作为一等指标。另一个不变量是 chunk 上限：单 batch 请求数与 chunk 上限共同约束 $\\epsilon$ 与尾延迟抖动，防止长请求凭 $\\beta$ 项饿死短请求。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-19\">十九 · 动态调参：监控量到控制量的映射</h3>\n<p>batch 上限与 chunk 大小不是静态配置，而是由监控量闭环驱动的控制量。映射关系可由第一节的推导直接读出：RTF 逼近 1 时，$\\tau$ 需要上调（等价于 chunk 变大），因为 $\\tau \\ge w(1+\\epsilon)$ 是硬下界；首包延迟逼近 SLO 时，$\\tau$ 需要下调以缩短首包等待，同时 batch 上限下调以减小 $\\epsilon$ 与抢占重算。两个方向冲突，所以调参必须是带优先级的：首包 SLO 为硬约束，先保它，RTF 约束退让到“不破 1”的边界；只有在首包达标计数稳定后，才用富余的 RTF 余量换吞吐。</p>\n<p>具体例子：混合长度流式请求下，短请求追求首包、长请求追求实时率，监控发现首包延迟抖动放大且 RTF 尚有余量，则下调 chunk 大小并同步下调 batch 上限，用吞吐换首包稳定；若发现 RTF 贴边而首包达标，则反向操作。这里有一个工程判断必须写死：chunk 大小的调整步长要与 $g$ 对齐粒度同量级，否则形状频繁跳变会把 $\\epsilon$ 的固定项推高，调参本身成为抖动源。量化沿用模型既有精度栈，调度层不改变数值格式，因此 $w$ 的变化只来自 chunk 大小与状态切换，不来自精度切换——这让上述映射在部署中可预测。规模上限受显存碎片与状态缓存容量约束，batch 过大时对齐浪费与抢占重算推高尾延迟抖动，需与 chunk 大小联合调参，单参数寻优会走进“压一头翘一头”的死角。</p>\n<p>最后落在可实现的判据上：每步调度结束后，用实测的 $T_{\\text{compute}}^{\\text{batch}}$ 与 $T_{\\text{audio}}^{\\text{batch}}$ 回填 RTF 估计，与预测值比对；偏差超过阈值说明 $\\epsilon$ 估计失准（多来自碎片或重算），此时应优先收缩 batch 上限而非调 chunk，因为 $\\epsilon$ 的漂移主要随 batch 规模放大。这条回填—比对—收缩的闭环，是把第一节的约束式变成运行时行为的最后一环。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-20\">二十 · 边界条件与失效模式：RTF 约束下的调度代价</h3>\n<p>该调度器的可行性并非无条件的，其成立的前提是 RTF ≤ 1 这一硬性约束在稳态下可被满足。RTF 的定义为批内计算时间与批内音频时长之比，即 <span class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}}$$</span>，当 RTF 逼近 1 时，系统已无余量吸收突发到达的请求，首包 SLO 的硬约束随即被击穿。推导的关键一步在于：批内音频时长由各请求当前 chunk 的音频长度之和决定，而计算时间随批大小近似线性增长但受对齐填充放大——若批内最长 chunk 与最短 chunk 相差 k 倍，则填充浪费使有效 RTF 抬升至名义值的 k 倍量级。这意味着调度器在混合长度负载下必须限制批内长度方差，否则 RTF 约束会先于显存约束成为瓶颈。系统代价直接体现为：为守住 RTF ≤ 1，调度器被迫缩小 batch 上限，GPU 利用率下降，吞吐让位于延迟。</p>\n<p>优先级公式 <span class=\"formula\">$$p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$$</span> 的工程含义是双刃的：第一项保证紧 SLO 请求优先入批，第二项防止长请求被无限饿死。但 β 取值过小则长请求在持续过载下永远排在短请求之后，β 过大则短请求的首包被已服务多 chunk 的长请求挤占，硬约束失效。失效条件可归纳为三类：其一，显存碎片——每请求独立的卷积与 KV 状态按生命周期分池分配，长对话下碎片累积触发 OOM 或强制驱逐，吞吐骤降；其二，抢占重算——优先级动态调整导致已分配 chunk 被撤回重算，尾延迟抖动放大；其三，对齐浪费——chunk 过大时首包延迟上升，chunk 过小则调度与状态切换开销占比过高，两者之间存在一个由 RTF 监控闭环确定的窄窗口。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>显存碎片累积</td><td>长对话、状态池未按请求回收</td><td>OOM 或强制驱逐，吞吐骤降</td></tr><tr><td>抢占重算</td><td>过载下优先级频繁翻转</td><td>尾延迟抖动放大</td></tr><tr><td>对齐填充浪费</td><td>批内 chunk 长度方差大</td><td>有效 RTF 抬升，batch 上限收缩</td></tr></tbody></table>\n<p>伪代码落到可实现层面，调度循环的骨架为：每步从就绪队列按 p_r 取候选，累计音频长度直至对齐边界或 batch 上限，前向计算后将输出按请求路由回各自流，完成者释放状态、新请求插入空槽；监控线程以首包延迟与 RTF 为反馈量，动态调整 batch 上限与 chunk 大小，并对抢占撤回的 chunk 做重算补偿。适用边界因此明确：请求长度方差大且首包 SLO 严格的在线服务是主战场，规模上限受显存碎片与状态缓存容量约束，batch 过大时对齐浪费与重算抖动会抵消连续批处理的收益，需与 chunk 大小联合调参而非单独放大 batch。</p>\n<h3 id=\"alg-stream-batch-scheduler-sec-21\">二十一 · 负载配方的三个坐标：形态、长度分布、并发</h3>\n<p>本调度器的负载配方不是一句“混合长度请求”就能打发的，它由三个正交坐标决定：请求形态（纯 TTS 单向流、语音对话双向流、编解码 LM 流式生成）、长度分布（首包 chunk 数、总音频时长、尾部静音比例）、并发与批大小（同时在途请求数、单 batch 请求上限、chunk 上限）。三者共同决定调度器是否有活可干。若形态单一、长度方差小、并发恒定，chunk 级连续批处理退化为静态批，收益归零；若长度方差大、到达呈突发、并发越过显存可承载的状态缓存容量，调度器才真正进入它擅长的区间。工程上判断“负载是否对口”，看的是长度分布的方差与首包 SLO 的严格程度是否同时成立——只有短请求被长请求拖累时，按 chunk 增删才有意义。</p>\n<p>把配方写成可校验的形式，调度器每步要满足的约束是：</p>\n<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>\n<p>这条式子把负载配方翻译成两个可观测指标：首包延迟达标计数（硬约束）与 RTF 不超 1（软目标）。配方设计的实质，是让这两个指标在给定长度分布与并发下同时可达。若长度分布里长请求占比过高，RTF 逼近 1，任何抢占重算都会把 RTF 推过 1，此时配方本身就不成立，不是调参能救的。</p>\n<p>具体例子：一路语音对话服务，短请求为 1–2 个 chunk 的应答确认，长请求为数十 chunk 的连续叙述，两者混在同一队列。若按静态批一次成型，短请求必须等长请求的最后一个 chunk 才算完，首包延迟被拉到长请求的时长量级；按 chunk 连续批处理，短请求在第一个 chunk 前向完成后即可路由输出并释放槽位，首包延迟只取决于它自己的 chunk 计算时间。代价是长请求的状态缓存必须一直驻留，显存占用随并发线性上升。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-22\">二十二 · 长度分布决定对齐浪费与状态碎片</h3>\n<p>batch 内长度对齐到 chunk 边界是本调度器的固定动作，但浪费量由长度分布直接决定。设 batch 内各请求当前 chunk 的有效 token 数为 $l_i$，对齐后统一填充到 $\\max_i l_i$，则算力浪费比例为 $1 - \\sum_i l_i / (B \\cdot \\max_i l_i)$，其中 $B$ 为 batch 请求数。长度分布越离散，这个比例越高：短 chunk 与长 chunk 混批时，短请求的槽位大部分在做无效填充计算。chunk 大小是这里的关键旋钮——chunk 过大，单 chunk 内 token 数多，对齐的相对浪费下降，但首包延迟上升（首包必须等整个 chunk 算完）；chunk 过小，对齐浪费占比上升，且调度与状态切换开销在总时间中的占比变高。工程判断是：chunk 大小应取使“首包延迟预算减去固定开销”仍能容纳一个 chunk 前向的最大值，而不是凭经验拍一个固定 token 数。</p>\n<p>长度分布还决定状态碎片的累积速度。每请求独立的卷积状态与 KV 缓存按请求生命周期分配与回收，长对话请求的状态缓存持续驻留，短请求频繁进出造成分配器在池中留下空洞。碎片不是一次性爆发的，而是随长对话请求数与并发上升逐步累积，直到某次新请求插入空槽时找不到连续可用的状态块，触发强制驱逐或 OOM。这里的系统代价是显存而非算力：碎片化让有效状态缓存容量低于标称值，可承载并发被动下降，吞吐随之骤降。配方上应对的办法是把状态缓存按 chunk 数分档预分配、限制单请求状态上限，而不是等 OOM 后再做驱逐。</p>\n<p>具体例子：一批请求里 80% 是 3 chunk 以内的短应答、20% 是 40 chunk 以上的长叙述。短请求每步进出，状态块反复分配释放；长请求状态块长期占用。若不限制单 batch 请求数与 chunk 上限，长请求会把短请求挤出可用槽位，短请求排队等状态块，首包延迟抖动被放大——这正是“长请求饿死短请求”的显性表现。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-23\">二十三 · 并发与批大小：上限由状态缓存而非算力决定</h3>\n<p>并发上限在本调度器里不由 GPU 算力峰值决定，而由状态缓存容量与对齐浪费共同决定。设单请求平均状态缓存为 $S$，可用状态池为 $M$，则理论并发上限为 $M/S$；但碎片化使有效上限低于该值，且 batch 越大对齐浪费越高，单步前向时间 $T_{\\text{compute}}^{\\text{batch}}$ 随 $B$ 增长而非线性。RTF 约束 $\\text{RTF} \\le 1$ 因此转化为对 $B$ 的上界：当 $B$ 增大到对齐浪费与状态切换开销使单步前向时间超过该 batch 覆盖的音频时长时，RTF 破 1，实时性失守。调度器监控首包延迟与 RTF 动态调整 batch 上限，本质是在这条上界附近做闭环，而不是把 batch 开到显存能塞下的最大值。</p>\n<p>并发形态还影响优先级公式的实际行为。优先级 $p_r = \\alpha\\cdot 1/\\mathrm{SLO}_r + \\beta\\cdot n^{\\mathrm{served}}_r$ 中，$n^{\\mathrm{served}}_r$ 项让已服务 chunk 多的请求获得更高优先级，防止长请求被无限推迟；但当并发突增、大量新请求涌入时，新请求的 $n^{\\mathrm{served}}_r$ 为 0，若 $\\alpha$ 权重不足以让严格 SLO 的新请求压过已服务的长请求，首包硬约束就会被违反。配方上要求 $\\alpha$ 与 $\\beta$ 随负载状态调整：过载时提高 $\\alpha$ 保首包，轻载时提高 $\\beta$ 让长请求推进，避免长尾被饿死。这是两级 SLO（首包硬约束、长尾软目标）在参数层面的落地。</p>\n<p>具体例子：并发从常态突增到数倍，队列里既有 SLO 极紧的短请求，也有已服务多个 chunk 的长请求。若沿用轻载时的权重，长请求凭 $n^{\\mathrm{served}}_r$ 持续占据 batch 槽位，短请求首包延迟超标；调度器需在检测到首包延迟超阈值时切换权重并触发抢占，被抢占的长请求已分配 chunk 需重算，尾延迟抖动上升——这就是过载下“保首包、牺牲长尾吞吐”的代价，配方必须预先接受它。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-24\">二十四 · 负载不对时的三种失败形态</h3>\n<p>第一种是长度分布过于集中。若所有请求长度几乎一致、到达均匀，chunk 级增删没有可调度空间，每步 batch 组成稳定，调度开销纯属额外成本，静态批反而更省。此时对齐浪费低、状态碎片少，但调度器的优先级计算与状态切换在总时间中占比上升，收益为负。判断信号是首包延迟方差很小、RTF 长期远低于 1——说明系统不在需要连续批处理的区间。</p>\n<p>第二种是 chunk 与 SLO 不匹配。chunk 过大时，首包必须等整个 chunk 前向完成，即使 batch 很小、GPU 空闲，首包延迟也被 chunk 时长下限锁死；chunk 过小时，调度与状态切换开销占比过高，单步有效计算被固定开销稀释，RTF 上升。这两种失配都不是靠调 batch 上限能修的，必须回到 chunk 大小与首包 SLO 的联合标定。系统代价分别落在延迟下限与吞吐效率上，方向相反，配方要的是两者之间的可行带而非最优点。</p>\n<p>第三种是状态碎片触发的吞吐崩塌。长对话请求占比高、并发持续高位时，独立卷积与 KV 状态造成显存碎片累积，长对话下碎片累积触发 OOM 或强制驱逐，吞吐骤降。这种失败不是渐进的，而是越过某个碎片阈值后突然发生，监控上表现为可用状态块数骤减、驱逐次数跳升。配方上的防御是限制单 batch 请求数与单请求 chunk 上限、按生命周期回收状态、对长请求设状态驻留上限，把碎片累积速率压在回收速率之下。</p>\n<p>具体例子：一路编解码 LM 流式生成服务，长对话请求占比上升后，状态缓存池被长请求占满，新短请求插入空槽失败被拒或排队，首包延迟硬约束批量违反；调度器被迫驱逐部分长请求状态，被驱逐请求重来时需重算已服务 chunk，算力被重复消耗，RTF 进一步恶化，形成正反馈。这是负载配方与状态管理脱钩的典型后果。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-25\">二十五 · 配方标定的工程判据</h3>\n<p>把负载配方落到可执行判据，需要三个观测量同时在线：首包延迟分布的分位数（硬约束是否守住）、RTF 的滑动均值（实时性余量）、状态池的碎片率与驱逐次数（容量是否见底）。三者中任一越界，配方即进入不对的区间，调参顺序应是先 chunk 大小、再 batch 上限、最后优先级权重——因为 chunk 决定延迟下限与对齐浪费的量级，batch 上限决定 RTF 上界，权重只影响过载时的分配公平性，顺序颠倒会在错误的量级上做微调。量化沿用模型既有精度栈、调度层不改数值格式，这一点使配方标定不必考虑精度切换带来的算力突变，只需盯住上述三个观测量。</p>\n<p>配方还须与部署形态对齐：单机多卡或单卡多流下，状态缓存分池分配，跨卡请求不共享状态池，因此每卡的并发上限独立计算，负载均衡策略要把长请求与短请求按池容量分摊，避免某卡被长请求占满而另一卡空转。这是配方在部署层的延伸，不属于调度器内部逻辑，但决定了调度器看到的并发是否真实可达。</p>\n<p>最后一条判据是抢占重算的补偿预算。优先级抢占导致已分配 chunk 重算，重算量应计入 RTF 的分子而非当作偶发开销忽略；当重算量在总计算中占比上升到使 RTF 逼近 1 时，说明抢占过于频繁，配方应转为限制新请求插入速率而非继续抢占。这条判据把“保首包、牺牲长尾”从口号变成可核算的预算线：首包硬约束的守住，必须以 RTF 不破 1 为前提，否则牺牲的不只是长尾吞吐，而是整个服务的实时性底线。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-26\">二十六 · 负载配方与失效边界：什么时候这套调度器会反噬</h3>\n<p>这套 chunk 级连续批处理并非通用解，它的收益完全建立在“请求长度方差大、首包 SLO 严格、到达时间分散”这一负载配方上。判据是双目标的可行性：<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>RTF 逼近 1 时，任何抢占重算或对齐填充都会把系统推过实时线，此时调度器只能靠牺牲长尾来保首包。反过来，若请求长度高度同质（例如固定时长播报），静态批一次成型反而更省——每步增删请求的状态切换与优先级计算成了纯开销。</p>\n<p>负载不对时的失效是分层的。第一层是显存：每请求独立的卷积状态与 KV 分池分配，在长对话、多轮语音会话下碎片持续累积，最终触发 OOM 或强制驱逐，吞吐骤降而非缓慢退化。第二层是尾延迟：优先级公式 $$p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$$ 在过载时频繁触发抢占，已分配的 chunk 需重算补偿，抖动被放大；持续过载下长请求因 $n^{\\mathrm{served}}_r$ 增长慢而被反复挤出，形成饿死。第三层是 chunk 尺寸的两难：chunk 过大则首包延迟上升，过小则调度与状态切换开销占比过高，batch 内长度对齐到 chunk 边界的填充浪费随 batch 上限同步放大。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>主要代价</th><th>工程判断</th></tr></thead><tbody><tr><td>长短混合、到达分散</td><td>对齐填充 + 状态碎片</td><td>适配，需限制 batch 请求数与 chunk 上限</td></tr><tr><td>长度同质、批量离线</td><td>每步调度开销纯浪费</td><td>退回静态批更优</td></tr><tr><td>持续过载、长请求为主</td><td>抢占重算、尾延迟抖动、饿死</td><td>保首包弃长尾，或扩容而非调参</td></tr></tbody></table>\n<p>因此容量规划必须把“状态缓存容量”而非峰值算力当作第一约束：batch 上限与 chunk 大小要联合调参，单批请求数设硬顶防止长请求独占槽位，并对抢占重算做补偿记账。当监控显示 RTF 长期贴近 1 且首包延迟分布右尾抬升，说明负载已越出配方边界，此时继续加大 batch 只会把对齐浪费与重算开销转化为尾延迟抖动，正确动作是拆分实例或按 SLO 分级隔离流量。</p>\n<h3 id=\"alg-stream-batch-scheduler-sec-27\">二十七 · 硬件档位的选型判据：从 RTF 余量反推</h3>\n<p>部署配方的第一步不是选卡，而是先算清一条请求链路上 RTF 的预算分配。流式 TTS 与语音对话的 RTF 定义为批量前向耗时与对应音频时长之比，约束条件是 RTF ≤ 1 且首包 SLO 逐请求满足。工程上把这个约束拆成三段：编解码器/声学模型前向、声码器合成、调度与状态搬运。三段中任何一段吃掉过多余量，都会让 chunk 级连续批处理失去增删请求的空间——因为调度器每步能拼多大的 batch，取决于单 chunk 前向在预算内还剩多少时间。</p>\n<p>硬件档位的判据由此而来：给定目标并发流数 N 与 chunk 时长 T<sub>c</sub>，单卡需要提供的有效算力应满足 N·T<sub>c</sub>·RTF<sub>target</sub> 的前向吞吐。B200/B300 单卡与 GB200/GB300 NVL72 机架的差别不在单请求延迟，而在能容纳的并发流数与状态缓存池容量。单卡多流适合中等并发、首包 SLO 紧的场景，状态池小、碎片可控；NVL72 档位适合高并发混合长度负载，但跨卡的状态路由与输出回流会引入额外跳数，必须把这段开销计入首包预算，否则调度器会误判优先级。</p>\n<p>一个具体例子：同一套编解码器 LM，单卡部署时把 chunk 设为较短以压首包，batch 上限受显存状态池限制；迁到机架档位后若沿用同一 chunk，跨卡路由开销会吃掉首包余量，正确做法是把 chunk 略微放长、把省下的调度步数换成更大的 batch，用吞吐换回延迟稳定性。这里没有普适数字，判据是监控到的首包延迟分布与 RTF 曲线是否同时收敛。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-28\">二十八 · 并行拓扑：状态归属决定切分方式</h3>\n<p>流式批调度的并行拓扑不能照搬训练侧的切分逻辑，因为每个请求携带独立的 KV 与卷积状态，状态的归属决定了通信模式。可行的拓扑有三类：单卡多流（所有请求状态在同一显存池，零跨卡状态通信）、按请求分片的卡间并行（请求级负载均衡，状态随请求驻留单卡）、以及模型并行（层切分，每步前向需跨卡同步激活）。前两类对 chunk 级调度友好，第三类会把每步前向变成集合通信，调度器增删请求的自由度被通信延迟锁死。</p>\n<p>伪代码层面的判断很直接：调度步内先做请求选择与长度对齐，再发起前向；若拓扑是模型并行，对齐后的 batch 必须整体参与同步，抢占一个请求意味着整批重排，重算代价按 batch 规模放大。因此部署配方里优先选请求级分片，把模型并行限制在单请求都无法容纳的极端档位。</p>\n<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>\n<p>代价体现在带宽与延迟两侧：请求级分片下，输出按请求路由回各自流的回流路径是主要延迟项；模型并行下，每 chunk 前向的跨卡激活同步是主要延迟项。工程判断是——只要单卡状态池能装下目标并发流的 KV 与卷积状态，就不要引入模型并行，把跨卡带宽留给输出回流与状态迁移。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-29\">二十九 · 量化方案：调度层不碰数值格式</h3>\n<p>量化沿用模型既有精度栈，调度层不改变数值格式——这条约束的意义在于把量化决策与批调度解耦。NVFP4/FP8 的选择影响的是单 chunk 前向的算力与显存占用，进而影响 batch 上限与状态池容量，但不改变调度器的优先级公式与增删时机。部署配方里应把量化档位作为输入参数：给定精度栈，测出单 chunk 前向耗时与每请求状态字节数，再反推 batch 上限。</p>\n<p>具体机制上，量化压缩的是权重与激活，KV 与卷积状态是否低比特化是独立决策。状态低比特化能显著扩大状态池、缓解碎片，但会引入状态反量化的额外步骤，落在每步前向的关键路径上。因此配方里通常保持状态为较高精度、仅对权重与激活用量化格式，把显存压力交给状态池的分池分配与生命周期回收来解决。</p>\n<p>代价核算：量化档位提升带来的算力节省会转化为更大的可行 batch，但 batch 变大后长度对齐浪费同步上升，两者在某个点上抵消。可复现的做法是固定 chunk 与 SLO，扫描量化档位与 batch 上限的二维网格，取首包延迟满足硬约束下 RTF 最低的组合，而不是单看单 chunk 前向速度。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-30\">三十 · KV 与卷积状态策略：分池、对齐与回收</h3>\n<p>状态管理是本调度器最容易被低估的部分。每个请求持有独立的 KV 与卷积状态，按请求生命周期分配与回收；部署配方要求把这些状态分池管理，而不是与激活共用一块大缓冲。分池的好处是碎片被限制在状态池内部，长对话累积的碎片不会污染前向激活空间；代价是池容量需要按并发流数与最长对话预估，预估偏小会触发强制驱逐。</p>\n<p>批内长度对齐到 chunk 边界是减少填充浪费的关键手段：对齐粒度取 chunk 而非 token，使填充量上界为 batch 内请求数乘以 chunk 长度差。chunk 过大时对齐浪费与首包延迟同时上升，chunk 过小时调度与状态切换开销占比过高——这条失败模式在配方里必须用参数上下限锁住。</p>\n<p>回收策略与优先级抢占耦合：被抢占请求的已分配 chunk 需要重算补偿，其状态不能立即释放，否则重算要从头再来。配方里应给被抢占请求保留一段状态驻留窗口，窗口长度按重算补偿的 chunk 数设定。显存代价是驻留窗口内的状态无法复用，吞吐代价是窗口期内可用槽位减少；工程判断是窗口长度取重算 chunk 数的上界，宁可短暂少几个槽位，也不要让长请求在过载下被反复清零。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-31\">三十一 · 调度参数：优先级权重与动态上限</h3>\n<p>优先级形式化为 p<sub>r</sub> = α·(1/SLO<sub>r</sub>) + β·n<sup>served</sup><sub>r</sub>，前者让首包约束紧的请求优先，后者让已服务多 chunk 的长请求不被饿死。部署配方里 α 与 β 不是自由超参，而是由两级 SLO 结构决定：首包延迟是硬约束，长尾吞吐是软目标，过载时保首包、牺牲长尾。因此 α 应显著大于 β，β 的作用仅是防止长请求在持续过载下被无限推迟。</p>\n<p>动态上限包括单 batch 请求数与 chunk 上限，二者由监控的首包延迟与 RTF 联合调整。可复现的调整逻辑是：当首包延迟分位数逼近硬约束时，先降 batch 请求数上限，再考虑缩短 chunk；当 RTF 长期低于 1 且首包余量充足时，反向放宽上限以提吞吐。顺序不能颠倒，因为缩 chunk 会同时抬高调度开销占比，先动 batch 上限的副作用更小。</p>\n<p>一个具体例子：混合长度负载下，短请求集中到达时若 batch 上限过高，短请求会与长请求同批对齐，首包被拖长；此时降上限让短请求单独成小批，首包恢复，长请求转入下一批。代价是 GPU 利用率短暂下降，RTF 上升但仍低于 1，属于可接受的交换。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-32\">三十二 · 可复现配置思路与稳定性锁</h3>\n<p>把上述选择串成一条可复现路径：先定硬件档位与并行拓扑（优先单卡多流或请求级分片），再固定量化档位并测出单 chunk 前向耗时与每请求状态字节，据此算出状态池容量与 batch 上限初值；随后设定 chunk 上下限与对齐粒度，最后用 α、β 与两级 SLO 锁定优先级行为。每一步的输出都是下一步的输入约束，避免参数之间互相漂移。</p>\n<p>稳定性锁有三条：限制单 batch 请求数与 chunk 上限，防止长请求饿死短请求；对抢占导致的已分配 chunk 做重算补偿并保留状态驻留窗口；把状态池容量与最长对话预估绑定，碎片累积到阈值时主动驱逐而非等到 OOM。失败模式的根因是每请求独立卷积与 KV 状态造成显存碎片，长对话下碎片累积触发 OOM 或强制驱逐，吞吐骤降——因此碎片监控指标应作为配方的一部分，与首包延迟、RTF 同列观测。</p>\n<p>最终落在一条工程判断上：部署配方的正确性不取决于单项参数最优，而取决于 chunk 大小、batch 上限、状态池容量三者是否在同一组 SLO 约束下自洽；任何一项单独调优都会把压力转移到另外两项，表现为尾延迟抖动或吞吐骤降。可复现的配置思路就是把这三者作为联合变量扫描，用首包延迟硬约束筛掉不可行组合，再在可行域内取 RTF 最低点。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-33\">三十三 · 配方落地后的边界：状态碎片、抢占重算与 chunk 双刃</h3>\n<p>这套配方真正难的地方不在“怎么配”，而在“配完之后在哪里失效”。状态分池分配是显存侧的硬约束：每个请求携带独立的卷积缓存与 KV 状态，按生命周期回收，但回收时机取决于 chunk 完成而非请求结束，于是池内出现大小不一、无法合并的空洞。长对话场景下，碎片随会话数线性累积，直到某次新请求找不到连续块，触发强制驱逐——驱逐本身不报错，却把在途请求的进度清零，吞吐呈台阶式下跌。工程上必须给状态池设水位线与单请求状态上限，并在驱逐前优先淘汰已服务 chunk 数高、剩余 token 少的请求，用“丢长尾”换“保池子”。代价是显存占用从“按峰值请求数”变成“按峰值请求数 × 状态粒度”，粒度越细，碎片越少，但分配器元数据开销越高。</p>\n<p>抢占是第二个失效点。优先级式 $p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$ 在过载时决定增删，被删请求已算完的 chunk 若尚未路由输出，就必须重算。重算量正比于被抢占请求的 chunk 深度，尾延迟抖动因此被放大：短请求首包变快，长请求的完成时间方差变大。补偿手段是给被抢占请求保留其已提交 chunk 的输出缓冲，重算只补未提交部分，代价是缓冲占用额外显存，与状态池争抢同一块预算。持续过载下，$\\beta$ 项会不断推高长请求优先级，但若 batch 上限被硬性锁死，长请求仍可能被短请求的洪峰反复挤出，形成饿死。</p>\n<p>chunk 大小是配方里唯一同时作用于延迟与吞吐的旋钮。对齐到 chunk 边界能减少填充浪费，但 chunk 过大时，首包必须等一个完整 chunk 前向，SLO 硬约束被直接击穿；chunk 过小时，每步调度与状态切换的固定开销占比上升，RTF 逼近 1 的上限。约束可写成：</p>\n<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>\n<p>它说明 chunk 缩小改善首包项，却把 RTF 推向边界；chunk 放大改善 RTF，却牺牲首包。配方必须把 chunk 与 batch 上限联合标定，而不是分别调优。一个可复现的判断是：先在目标硬件档位上固定量化方案与并行拓扑（调度层不改数值格式），用混合长度负载扫 chunk ∈ {小、中、大} 三档，记录每档的首包延迟分布与 RTF，选满足硬 SLO 且 RTF 留有余量的最大 chunk，再以该 chunk 反推 batch 上限，使对齐浪费与抢占重算的尾抖动落在可接受区间。规模上限由此确定：显存碎片容量决定会话数上限，batch 上限决定单步算力上限，两者任一先到，配方即失效。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>配方应对</th></tr></thead><tbody><tr><td>状态碎片累积</td><td>OOM 或强制驱逐，吞吐骤降</td><td>状态池水位线 + 按剩余 token 淘汰</td></tr><tr><td>优先级抢占</td><td>已分配 chunk 重算，尾延迟抖动</td><td>保留已提交输出缓冲，只补未提交段</td></tr><tr><td>chunk 失配</td><td>首包超 SLO 或 RTF 越界</td><td>chunk 与 batch 上限联合标定</td></tr></tbody></table>\n<h3 id=\"alg-stream-batch-scheduler-sec-34\">三十四 · 显存：碎片先于容量见底</h3>\n<p>流式多模态批调度在规模上去以后，第一个崩的通常不是算力，而是显存。原因不在总容量，而在分配形态：每个请求持有独立的卷积状态与 KV 缓存，生命周期由音频流长度决定，长短请求混跑时这些状态块大小不一、释放时刻不一，形成典型的外部碎片。调度器每步按 chunk 拼批，批内请求数动态增删，状态池的分配与回收节奏与 batch 组成不同步，碎片率随长对话累积单调上升。</p>\n<p>把碎片代价写成可观测的量：设状态池总容量为 $M$，单请求状态占用 $s_r$（随已服务 chunk 数增长），碎片率为 $\\phi$，则任意时刻可接纳的并发请求数上界为</p>\n<div class=\"formula\">$$N_{\\max} \\approx \\left\\lfloor \\frac{M(1-\\phi)}{\\max_r s_r} \\right\\rfloor$$</div>\n<p>分母取最大单请求占用而非均值，是因为长请求的状态块无法被拆分安置。$\\phi$ 从 0.1 涨到 0.4，$N_{\\max}$ 直接掉三成，而 GPU 计算利用率看起来还没满——这就是“显存先崩”的典型信号：SM 占用率正常，调度器却开始拒绝新请求或触发强制驱逐。工程上的判断点是盯 $\\phi$ 的斜率而非绝对值：长对话场景下 $\\phi$ 随时长线性上升，一旦斜率不再收敛，扩容卡也救不了，必须改状态池的分池策略或引入按请求生命周期的紧凑回收。</p>\n<p>具体例子：一路 30 秒以上的长对话请求持续占用状态块，同时每秒有若干短请求进出。短请求的状态块在池中反复分配释放，留下大量小于单请求需求的空洞；长请求的状态块因为要扩增，被迫搬到池尾部，搬迁本身产生显存带宽开销与同步停顿。结果是短请求首包延迟抖动、长请求扩增失败，两类 SLO 同时受损。这不是容量问题，是布局问题。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-35\">三十五 · 带宽：对齐填充与状态读写的双重税</h3>\n<p>批内长度对齐到 chunk 边界是调度器的必要动作，但它是纯浪费的算力与带宽。设批内有 $B$ 个请求，各自当前 chunk 有效长度为 $l_i$，对齐目标为 $L=\\max_i l_i$，则填充浪费比例为</p>\n<div class=\"formula\">$$w = 1 - \\frac{\\sum_i l_i}{B\\cdot L}$$</div>\n<p>$w$ 在混合长度负载下可以很高：短请求的 chunk 被拉长到长请求的长度，多出来的位置算的是填充 token，却照样走完 MMA 与状态读写。更隐蔽的是状态带宽：每步前向除了读权重，还要为每个请求读写其卷积/KV 状态，状态访问量随 $B$ 线性增长，而权重读取量基本固定。规模上去后，状态读写占总带宽的比例上升，HBM 带宽成为硬瓶颈，SM 反而在等数据。</p>\n<p>代价可以定性排序：当 $B$ 较小，权重带宽主导，扩 batch 几乎线性提升吞吐；当 $B$ 增大到状态访问量与权重访问量同量级，边际吞吐迅速衰减，此时继续加 batch 只增加 $w$ 与状态带宽，不增加有效吞吐。这就是“batch 上限”的真实来源——不是显存放不下，是带宽摊薄失效。工程判断：把 chunk 大小与 batch 上限联合调参，chunk 增大降低调度与状态切换的固定开销占比，但抬高首包延迟；chunk 减小则相反。二者存在一个使有效吞吐最大的折中点，且该点随负载长度方差移动，必须由监控的首包延迟与 RTF 动态驱动，而不是写死。</p>\n<p>具体例子：一批请求里多数是 0.5 秒级短句、少数是数秒长句，对齐后短句的有效计算占比被压低，长句的状态读写又把带宽吃满。观测到的现象是 RTF 看似达标、GPU 利用率却不饱和，尾延迟在长句上堆积。此时正确的动作是拆批——按长度分桶而非强行混批，牺牲一点调度灵活性换回带宽效率。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-36\">三十六 · 通信：状态分池跨卡后的隐性同步</h3>\n<p>单卡多流时通信不是问题，一旦状态池分到多卡、或多机部署，通信代价就从“可忽略”变成“决定尾延迟”。流式调度的通信模式与训练不同：不是规整的大规模集合通信，而是每步、每请求、小消息量的状态同步与输出路由。消息小、频次高，延迟由启动开销主导而非带宽主导，NCCL 的集合通信原语在这种形态下效率不高，NIXL 一类点对点传输更贴合，但需要调度器显式管理传输句柄与完成事件。</p>\n<p>把每步通信代价写成：设跨卡请求数为 $k$，单次状态同步固定开销为 $t_s$，则每步额外延迟约 $k\\cdot t_s$ 量级（并发传输可重叠，但受链路与完成事件排队约束）。当 chunk 很小、步频很高时，$k\\cdot t_s$ 会与单步计算时间同量级，通信从后台走到前台。规模上去后先崩的位置就在这里：不是链路带宽不够，是每步的固定同步开销把 RTF 推过 1。</p>\n<p>具体例子：一个请求的解码状态在 A 卡、声学 chunk 计算在 B 卡，每步需要把状态从 A 传到 B 再回传。单步传输量很小，但步频是每几十毫秒一次，累积延迟直接体现在首包与后续 chunk 的间隔抖动上。工程判断：状态与计算尽量同卡亲和放置，跨卡只在请求迁移或负载均衡时发生；把跨卡同步从“每步”降为“每 chunk 组”，用更大的调度粒度摊薄固定开销，代价是首包延迟上升——这与 chunk 大小的调参是同一个权衡的另一面。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-37\">三十七 · 功耗与热：持续高占用的隐性上限</h3>\n<p>流式服务是长时在线负载，与离线批推理的短时冲刺不同。连续批处理把 GPU 利用率维持在较高水平，功耗随之稳定在高位，机架级功耗与散热成为规模上限。GB200/GB300 NVL72 这类整柜形态里，功耗预算是共享资源：单卡跑满会挤压同柜其他卡的可用余量，调度器若只按单卡视角扩 batch，会在机架层面触发降频，表现为尾延迟整体抬升而非个别请求变慢。</p>\n<p>代价机制：功耗约束下的有效算力随频率下降而下降，RTF 的分母（音频时长）不变、分子（计算时间）变长，于是原本达标的 batch 配置在热约束下不再达标。调度器必须把功耗视为与显存、带宽并列的一维资源，在过载时优先保首包 SLO 而非保吞吐——这与优先级公式 $p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$ 的取向一致：$\\alpha$ 权重在热约束下应上调，让首包硬的请求先拿到算力，长尾吞吐作为软目标被牺牲。</p>\n<p>具体例子：机架功耗接近上限时，调度器仍按原 batch 上限拼批，GPU 降频，所有请求的 chunk 间隔被拉长，首包延迟集体越线。正确的动作是主动下调 batch 上限与 chunk 上限，把利用率从“跑满”降到“留余量”，用少量吞吐换回延迟确定性。这是一个反直觉的工程判断：在功耗受限的整柜部署里，跑满不是最优，稳定留余量才是。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-38\">三十八 · 尾延迟：抢占重算与长请求饿死的叠加</h3>\n<p>尾延迟在流式批调度里不是统计噪声，是结构性产物，来源有二：优先级抢占导致已分配 chunk 重算，以及长请求在持续过载下被反复降级。前者是算力浪费，后者是公平性问题，二者叠加放大抖动。</p>\n<p>抢占重算的代价可以量化：设被抢占请求已计算的 chunk 数为 $n$，重算比例为 $\\rho$，则每次抢占浪费的计算量约为 $\\rho\\cdot n$ 个 chunk 的前向。$\\rho$ 取决于状态保存粒度——若只保存 chunk 边界状态，重算从边界起；若保存更细粒度中间状态，重算少但状态显存占用高。这是一个显存与算力的直接兑换，调度器需要在抢占决策时把重算代价计入优先级，而不是只看 SLO 紧迫度。</p>\n<p>长请求饿死的机制更隐蔽：优先级公式里 $n^{\\mathrm{served}}_r$ 随服务 chunk 数增长，本意是让已服务多的请求获得补偿，但在持续过载下，新到达的短请求因 $\\mathrm{SLO}_r$ 更紧而持续插队，长请求的 $n^{\\mathrm{served}}_r$ 增长不足以抵消 $\\frac{1}{\\mathrm{SLO}_r}$ 的差距，于是被无限期推迟。表现为长对话的后续 chunk 间隔越来越长，最终 RTF 越线。工程判断：给长请求设一个服务配额下限，或对 $n^{\\mathrm{served}}_r$ 采用非线性增长（如按已等待时长而非已服务 chunk 数计权），防止补偿项被紧迫度项永久压制。</p>\n<p>具体例子：过载时段内短请求密集到达，调度器每步优先选首包紧的请求，长请求的当前 chunk 反复落选，其状态块长期占用显存却不产出，既加剧碎片又拉长尾延迟。观测信号是长请求的 chunk 间隔分布右尾变厚，同时短请求首包达标率仍高——这说明调度器在正确地保首包，但公平性机制缺失。修复不是调 $\\alpha$，是补配额。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-39\">三十九 · 规模上去以后先崩的位置</h3>\n<p>把五个维度按“先崩顺序”排：单卡阶段，显存碎片先于容量见底，$\\phi$ 斜率是预警信号；batch 增大后，带宽摊薄失效，状态读写与对齐填充共同压低边际吞吐；跨卡/多机后，每步小消息同步开销把 RTF 推过 1，通信从后台走到前台；整柜部署时，功耗与热约束让“跑满”策略失效，降频表现为集体尾延迟抬升；最后，抢占重算与长请求饿死在持续过载下叠加，尾延迟抖动成为不可忽视的 SLO 违约源。</p>\n<p>这个顺序不是绝对的，取决于负载形态：短请求主导时碎片与通信先崩，长对话主导时带宽与饿死先崩。工程上可操作的判断是建立一张资源-信号对照表，把每个维度的早期信号映射到调度参数：$\\phi$ 上升对应状态池分池与紧凑回收；$w$ 上升对应按长度分桶拆批；每步通信延迟占比上升对应状态亲和放置与 chunk 组粒度；功耗接近上限对应主动下调 batch 与 chunk 上限；长请求 chunk 间隔右尾变厚对应服务配额下限。调度器的动态调参逻辑应当由这些信号驱动，而不是由单一 RTF 指标驱动——RTF 是结果，不是原因。</p>\n<p>最后落在具体机制上：把 batch 上限与 chunk 大小做成二维控制面，每个调度步根据当前 $\\phi$、$w$、通信延迟占比、功耗余量与长请求等待时长联合决策，优先级公式中的 $\\alpha,\\beta$ 随资源紧张程度自适应。这样做的代价是调度器自身逻辑变复杂、每步决策开销上升，但换来的是规模上去后各维度依次触顶时系统仍能守住首包硬约束——这正是流式多模态批调度在 Blackwell 上从“能跑”到“跑得稳”的分界线。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-40\">四十 · 规模上去以后，先崩的是状态池而不是算力</h3>\n<p>chunk 级连续批处理把利用率与首包延迟解耦，但代价全部沉在状态管理这一层。每个活跃请求都要独立持有卷积缓存与 KV，按生命周期分池分配；长对话把池子切得越碎，连续大块越少，分配器只能退化为小块拼凑。碎片累积到一定程度，即便总空闲显存够，也凑不出下一个 chunk 所需的连续段，触发强制驱逐甚至 OOM，吞吐骤降。这条边界不由 FLOPs 决定，而由“活跃请求数 × 单请求状态字节数 ÷ 最大可分配块”决定，因此扩 batch 上限之前，先算状态池的可容纳请求数上限。</p>\n<p>对齐浪费与抢占重算构成尾延迟抖动的两个来源。批内长度对齐到 chunk 边界后，短 chunk 被填充到批内最长，浪费比例随长度方差上升；chunk 过大则首包延迟上升，chunk 过小则每步调度与状态切换开销占比过高，二者需与 batch 上限联合调参。过载时按优先级抢占，被抢占请求已分配的 chunk 必须重算，重算量正比于抢占深度，尾延迟抖动随之放大。硬约束仍是首包 SLO，软目标是长尾吞吐：</p>\n<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>\n<p>RTF 逼近 1 意味着计算已无余量，任何抢占重算都会把长请求推过实时线。工程判断是：当活跃请求数增长使状态池接近饱和、且 RTF 的滑动均值持续贴近 1 时，扩容单卡流数已无收益，应先缩短 chunk 上限与单 batch 请求数，把碎片压下去，再考虑加卡；否则新增算力只会被状态切换与重算吃掉。</p>\n<h3 id=\"alg-stream-batch-scheduler-sec-41\">四十一 · 精度漂移：从数值格式到可观测指标</h3>\n<p>调度层不改数值格式，但调度层会改变数值格式暴露的方式。同一份 NVFP4/FP8 权重，在静态批里始终以固定 batch 形状前向；在 chunk 级连续批里，同一请求的相邻 chunk 可能落在不同 batch 形状、不同对齐长度、不同并发邻居上。tcgen05 的 MMA 指令对 K 维对齐、TMEM 分配与累加顺序敏感，batch 形状变化会改变归约树的形状，进而改变舍入误差的累积路径。这不是“精度变差”，而是“精度不再可复现”——同一请求重放两次，声学 chunk 的 logits 分布可能出现可测的偏移。</p>\n<p>诊断这类问题的抓手不是看单点误差，而是看跨 chunk 的一致性。对每个请求维护一条 chunk 级特征轨迹（例如码本 LM 的 top-k 概率质量、声学头的能量包络），计算相邻 chunk 之间的相对偏差：</p>\n<div class=\"formula\">$$\\delta_r = \\frac{1}{C_r}\\sum_{c=1}^{C_r}\\frac{\\lVert \\hat{y}_{r,c}-\\hat{y}_{r,c-1}\\rVert_2}{\\lVert \\hat{y}_{r,c-1}\\rVert_2+\\epsilon}$$</div>\n<p>当 $\\delta_r$ 在某个 batch 形状切换点出现阶跃，而该请求的输入并无对应突变，就指向数值路径问题而非模型问题。工程代价上，这条轨迹的采集本身要占显存与带宽：每 chunk 保留一个低维投影向量，按请求生命周期回收，单请求开销可控，但并发数千流时投影缓冲池会成为新的碎片源，必须与 KV 状态池分开管理。</p>\n<p>具体例子：一个长对话请求在第 40 个 chunk 后音色出现轻微金属感，重放同一文本在不同并发下复现率不同。定位手段是把该请求强制钉在固定 batch 形状（batch=1、对齐到 chunk 边界）重跑，若偏差消失，则确认是形状相关的归约路径差异，而非量化本身。回滚策略是调度层提供“形状钉住”开关，对已报障的请求降级为独占槽位，代价是吞吐下降，但能把问题隔离在单请求内而不污染整批。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-42\">四十二 · OOM 与碎片：状态池的生命周期账</h3>\n<p>本调度器的显存失败几乎不来自权重，而来自每请求独立的卷积状态与 KV 缓存。分池分配解决了“大块连续”问题，但没解决“生命周期不齐”问题：短请求释放的槽位尺寸与长请求需要的槽位尺寸不匹配，池内出现大量可用但不可用的空洞。长对话下碎片累积，最终触发 OOM 或调度器主动驱逐——驱逐本身是正确行为，但驱逐哪个请求决定了尾延迟的形状。</p>\n<p>把碎片量化成可调度信号：对每个状态池维护可用块尺寸直方图，定义碎片率</p>\n<div class=\"formula\">$$\\phi = 1-\\frac{\\sum_b n_b\\cdot s_b}{\\sum_b n_b\\cdot \\lceil s_b/\\text{align}\\rceil\\cdot\\text{align}}$$</div>\n<p>其中 $n_b$ 为尺寸 $s_b$ 的空闲块数量。$\\phi$ 越过阈值时，调度器应停止接纳新请求而非继续拼批——继续拼批只会让下一个 chunk 前向在分配阶段失败，把 OOM 从“拒绝服务”变成“中途崩溃”，后者对已建立流的破坏远大于前者。这是本调度器与静态批最不同的失败语义：静态批 OOM 发生在成型时，连续批 OOM 可能发生在任意一步。</p>\n<p>具体例子：NVL72 单节点上数十条长对话流并行，每条流持有独立卷积状态，chunk 边界对齐后单请求状态占用按 chunk 数线性增长。运行数十分钟后新请求插入失败率上升，而 GPU 利用率并未饱和——典型的碎片型 OOM，而非容量型 OOM。诊断看两个量：池内最大可用块尺寸是否仍大于单请求峰值需求（是则碎片），以及驱逐计数与首包延迟的分位曲线是否同步抬升（是则驱逐已开始伤 SLO）。回滚手段是缩短 chunk 上限、强制周期性状态整理（把存活请求迁移到紧凑槽位），代价是一次迁移期间该请求的 chunk 重算，尾延迟出现一次尖刺，需与 SLO 软目标权衡。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-43\">四十三 · 批抖动与路由不均：抢占的连锁反应</h3>\n<p>优先级公式 $p_r = \\alpha/\\mathrm{SLO}_r + \\beta n^{\\mathrm{served}}_r$ 在过载时驱动抢占。抢占的代价不是一次重算，而是重算引发的批组成变化：被抢占请求退出后，同批其他请求的对齐长度可能改变，调度器重新选批，原本已分配的 chunk 作废。若抢占频繁发生在 chunk 边界附近，batch 组成会在相邻步之间来回震荡，形成批抖动——GPU 利用率曲线出现高频锯齿，而首包延迟分位曲线同步恶化。</p>\n<p>抖动的根源是优先级函数的斜率。$\\alpha$ 过大时，任何新到的紧 SLO 请求都会触发抢占，长请求被反复打断；$\\beta$ 过小时，已服务 chunk 多的长请求得不到保护，在持续过载下被饿死。诊断不看单步决策，而看抢占率与重算率的比值：</p>\n<div class=\"formula\">$$\\rho = \\frac{\\#\\text{preempted chunks}}{\\#\\text{recomputed chunks}},\\quad \\text{健康区间由 chunk 上限与 batch 上限联合标定}$$</div>\n<p>$\\rho$ 接近 1 说明每次抢占都伴随等量重算，算力被纯粹浪费；$\\rho$ 远小于 1 说明抢占后请求长期得不到回插，饥饿正在发生。路由不均则表现为另一类抖动：多流/多卡部署下，某张卡上的请求因状态池更满而更早被驱逐，驱逐又把负载推向其他卡，形成负载在卡间来回迁移。诊断看每卡的首包延迟分位与驱逐计数的相关性，若强相关则路由层需要感知状态池水位，而非仅按请求数轮询。</p>\n<p>具体例子：双流全双工对话中，一路流的首包 SLO 远紧于另一路，$\\alpha$ 调高后紧 SLO 流首包达标率上升，但对侧流的 chunk 被反复抢占，其尾延迟尖刺出现在每轮对话切换点。回滚是把 $\\alpha,\\beta$ 退回上一组标定值，并把抢占限制在“仅当新请求尚未分配任何 chunk”时允许——已分配 chunk 的请求只做排队不做抢占，用吞吐换尾延迟稳定。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-44\">四十四 · 尾延迟尖刺：三个来源的分离</h3>\n<p>尾延迟尖刺在本调度器里有三个互不相同的来源，混在一起看分位曲线无法定位。第一是抢占重算，尖刺与抢占事件时间对齐；第二是 chunk 过大导致的首包延迟上升，尖刺表现为首包分位的整体抬升而非孤立尖峰；第三是状态池分配失败后的驱逐与重插，尖刺伴随 OOM 计数与池水位。分离手段是给每个 chunk 前向打三个时间戳：入批、前向开始、输出路由完成，分别归因到排队、计算、路由三段。</p>\n<p>排队段尖刺指向调度决策（抢占、批上限过小）；计算段尖刺指向对齐浪费与 batch 形状突变（长请求插入导致对齐长度跳变）；路由段尖刺指向输出侧背压——流式输出按请求路由回各自流，若下游消费慢，路由缓冲反压会阻塞调度器释放槽位，间接抬高后续请求的排队时间。这一条最容易被误判为 GPU 问题，实际是端到端流水线的背压传导。</p>\n<p>监控上，首包延迟与 RTF 必须按请求类别分层统计，而非全局平均。全局平均会把短请求的达标掩盖在长请求的恶化之下。分层后看每层的 P99 与驱逐率，若某层 P99 抬升而驱逐率为零，则尖刺来自抢占或对齐；若驱逐率同步抬升，则先修碎片与池水位。回滚的优先级顺序应是：先钉住 chunk 上限与 batch 上限（消除形状突变），再调 $\\alpha,\\beta$（消除抢占震荡），最后才动状态池整理策略——整理本身引入迁移重算，是最后手段。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-45\">四十五 · 监控面与回滚闸门</h3>\n<p>可观测面按四个维度组织，每个维度对应一类失败模式，且都必须能在不回放请求的前提下判定。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>指标</th><th>对应失败</th><th>回滚动作</th></tr></thead><tbody><tr><td>数值</td><td>chunk 级特征轨迹偏差 $\\delta_r$、形状切换点阶跃</td><td>精度漂移</td><td>形状钉住，降级独占槽位</td></tr><tr><td>显存</td><td>碎片率 $\\phi$、最大可用块尺寸、驱逐计数</td><td>OOM/碎片</td><td>停纳新请求、缩 chunk 上限、状态整理</td></tr><tr><td>调度</td><td>抢占率/重算率 $\\rho$、批组成震荡频率</td><td>批抖动/饥饿</td><td>退回 $\\alpha,\\beta$ 标定值、限抢占时机</td></tr><tr><td>端到端</td><td>分层首包 P99、RTF、路由段耗时</td><td>尾延迟尖刺</td><td>先钉上限，再调优先级，最后整理</td></tr></tbody></table>\n<p>回滚闸门的设计原则是“单向降级、可观测恢复”：每次回滚只动一个旋钮，且该旋钮的效果必须在下一次统计窗口内可见。例如把 batch 上限从标定值下调一档，观察首包 P99 是否回落、RTF 是否仍在 1 以下；若 RTF 跌破 1 说明降级过度，需回调。闸门不应自动连环触发，否则多个旋钮同时动作会让归因失效——这与抢占本身造成的批抖动是同一类问题，只是发生在运维层。</p>\n<p>具体例子：一次过载中，驱逐计数与首包 P99 同步抬升，运维先触发“停纳新请求”闸门，碎片率停止增长但 P99 未回落；随后发现路由段耗时也在抬升，判定为下游背压而非 GPU 侧问题，回滚方向转为放宽路由缓冲而非继续缩 batch。这个例子说明监控面必须包含路由段，否则会把背压误诊为调度失败，做出错误的降级动作。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-46\">四十六 · 工程判断：失败模式决定参数标定顺序</h3>\n<p>本调度器的参数不是独立可调的。chunk 大小决定对齐浪费与首包延迟的权衡，batch 上限决定抢占频率与碎片增长速率，$\\alpha,\\beta$ 决定抢占的触发条件，状态池整理策略决定碎片回收的代价。四者中任意一个单独调优都会把失败模式推到另一个维度：缩 chunk 降首包延迟但抬高调度开销占比，扩 batch 提吞吐但加速碎片累积，调高 $\\alpha$ 保首包但制造饥饿。</p>\n<p>因此标定顺序应由失败模式的代价排序决定，而非由吞吐目标排序。先固定 chunk 上限使对齐浪费可测，再固定 batch 上限使碎片增长可测，然后在该约束下标定 $\\alpha,\\beta$ 使抢占率与重算率 $\\rho$ 落在健康区间，最后才引入状态整理作为兜底。任何一步的监控指标越界，回滚到上一步的标定值，而不是在四维空间里同时搜索。这与静态批“一次成型、等最慢请求”的失败语义相反：静态批的失败是确定的、可预算的，连续批的失败是逐步累积的、需要在运行中持续观测的。判断一个部署是否健康，不看 GPU 利用率峰值，而看驱逐计数是否为零、$\\rho$ 是否稳定、分层首包 P99 是否与 SLO 同阶——三者同时成立，才说明 chunk 级连续批的增删时机与状态生命周期是匹配的。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-47\">四十七 · 过载边界：抢占重算、状态碎片与对齐浪费的三角</h3>\n<p>这套调度器在稳态下把首包延迟与利用率解耦，但它的失效几乎总在过载区被触发。优先级式 $p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$ 一旦被推高，抢占就变成常态：被踢出的请求其已分配的 chunk 必须重算，重算量正比于被抢占次数与已服务 chunk 数，尾延迟抖动因此被放大而非收敛。长请求在持续过载下 $n^{\\mathrm{served}}_r$ 增长却始终排不进 batch，形成饿死——这是“保首包、牺牲长尾”策略的必然边界，不是 bug，但必须在容量规划里显式计入。</p>\n<p>第二类失效来自状态管理。KV 与卷积状态按请求独立分池，长对话下每请求状态尺寸不一，释放与分配交错产生碎片；碎片累积到无法容纳新请求的连续块时触发 OOM 或强制驱逐，吞吐呈阶跃式下跌。诊断上应把“状态池占用率 / 最大连续空闲块”作为一级指标，而不是只看总显存。第三类是 chunk 与 batch 上限的联合调参失配：chunk 过大则首包延迟上升，chunk 过小则调度与状态切换开销占比过高；batch 内长度对齐到 chunk 边界虽减少填充，但 batch 过大时对齐浪费与抢占重算叠加，直接推高尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要指标</th><th>处置</th></tr></thead><tbody><tr><td>首包延迟尖刺</td><td>抢占次数/请求、重算 chunk 数</td><td>降 batch 上限、提 $\\alpha$</td></tr><tr><td>OOM 或强制驱逐</td><td>状态池碎片率、连续空闲块</td><td>缩 chunk、按生命周期回收</td></tr><tr><td>RTF 逼近 1</td><td>$\\text{RTF} = T_{\\text{compute}}^{\\text{batch}} / T_{\\text{audio}}^{\\text{batch}}$</td><td>增 chunk 或降并发</td></tr></tbody></table>\n<p>回滚必须按机制而非按版本：调度层不改变数值格式，因此精度问题应归因于模型既有精度栈而非调度器，回滚时只需冻结 chunk 大小与 batch 上限两个旋钮，并把抢占补偿开关关掉，让已分配 chunk 跑完再释放，用短时吞吐换尾延迟稳定。监控上以首包延迟分布的分位数与 RTF 联合判定，单看均值会掩盖抢占造成的长尾。</p>\n<h3 id=\"alg-stream-batch-scheduler-sec-48\">四十八 · 同族算法谱系与选择维度</h3>\n<p>流式多模态批调度不是孤立算法，它处在一个由“调度粒度 × 抢占策略 × 状态管理方式”张成的族谱里。同族成员至少包括：静态批处理（一次成型、等最慢请求）、固定窗口分块批（chunk 大小与 batch 上限预先钉死）、动态 chunk 连续批（本片段主题）、以及按请求优先级抢占的 SLO 感知批。选择时不能只看吞吐峰值，要沿四个维度打分：调度粒度（请求级 / chunk 级 / 子 chunk 级）、增删时机（批成型后不可变 / 每步可增删）、状态耦合度（共享 KV 池 / 每请求独立池 / 分页池）、过载行为（丢弃、排队、抢占重算）。这四个维度直接决定首包延迟抖动与 RTF 能否同时压住。</p>\n<p>把选择问题写成约束形式，就是本族共同的优化目标：</p>\n<div class=\"formula\">$$\\text{RTF} = \\frac{T_{\\text{compute}}^{\\text{batch}}}{T_{\\text{audio}}^{\\text{batch}}},\\quad \\max \\sum_i \\mathbb{1}[L_{\\text{first},i} \\le \\text{SLO}_i] \\;\\text{s.t.}\\; \\text{RTF} \\le 1$$</div>\n<p>静态批的可行域最窄：一旦 batch 成型，$L_{\\text{first},i}$ 由批内最慢请求决定，长请求会把短请求的首包拖到 SLO 之外，于是 $\\mathbb{1}[\\cdot]$ 大量取零；而 chunk 级连续批把 $L_{\\text{first},i}$ 与同批其他请求解耦，可行域显著变宽。代价落在状态侧：每请求独立的卷积/KV 状态让显存从“连续大块”退化为“多张小块”，碎片率上升。工程判断的分水岭是——当请求长度方差（用音频时长分布的 P95/P50 比值衡量）超过一个可感知阈值、且首包 SLO 是硬约束时，静态批必然失效，必须上 chunk 级连续批；反之若请求长度高度均一、SLO 宽松，静态批的对齐浪费反而更小。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-49\">四十九 · 决策表：按负载形态选族内成员</h3>\n<p>下表把族内四种典型形态与适用条件对齐。表中“抢占”一列指过载时是否允许把已分配 chunk 撤回重算；“状态池”指 KV 与卷积状态的分配方式。选择顺序建议自上而下：先看长度方差，再看 SLO 硬度，最后看显存余量。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>调度粒度</th><th>增删时机</th><th>抢占</th><th>状态池</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>静态批</td><td>请求级</td><td>成型后不可变</td><td>无</td><td>连续大块</td><td>长度均一、SLO 宽松、离线或准在线</td><td>等最慢请求，GPU 空转</td></tr>\n<tr><td>固定窗口分块批</td><td>chunk 级</td><td>窗口边界可换</td><td>无</td><td>每请求独立</td><td>长度中等方差、chunk 可预估</td><td>窗口边界处首包抖动</td></tr>\n<tr><td>动态 chunk 连续批</td><td>chunk 级</td><td>每步可增删</td><td>可选</td><td>每请求独立分池</td><td>长度方差大、首包 SLO 硬</td><td>碎片、对齐浪费、状态切换</td></tr>\n<tr><td>SLO 感知抢占批</td><td>子 chunk 级</td><td>每步可增删+撤回</td><td>强制</td><td>分页池</td><td>持续过载、多级 SLO 并存</td><td>重算尾延迟抖动、饿死长请求</td></tr>\n</tbody></table>\n<p>决策表背后的量化判据是优先级函数本身：</p>\n<div class=\"formula\">$$p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$$</div>\n<p>$\\alpha$ 主导“谁的首包更急”，$\\beta$ 主导“谁已经被服务得够多、该让位”。当 $\\beta/\\alpha$ 偏大，调度偏向公平、长请求不易饿死，但短请求首包会被推后；当 $\\beta/\\alpha$ 偏小，调度偏向首包硬约束，过载时大量长请求被反复抢占重算，尾延迟抖动放大。工程上把 $\\beta/\\alpha$ 当作一个可调旋钮，与 batch 上限联合标定：batch 上限越大，对齐浪费与抢占重算的绝对量越大，$\\beta/\\alpha$ 应相应调大以抑制抖动。一个具体例子：语音对话服务里短问句（几百毫秒音频）与长叙述（数十秒）混流，若把 $\\beta/\\alpha$ 设得过小，长叙述在持续过载下每次刚攒够 chunk 就被撤回，实际产出趋近于零；把 $\\beta$ 提上来后，长请求获得稳定推进，代价是短问句首包 P99 上升，需要靠限制单 batch 请求数把这段上升压在 SLO 内。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-50\">五十 · 与相邻流式解码算法的接口选择</h3>\n<p>批调度处在流水线的中枢，向上要对接编解码器分块推理与 RVQ 渐进解码，向下要对接声码器分块批合成。接口选择的关键是“chunk 边界是否对齐”。若上游编解码器按固定 chunk 产出 token、下游声码器按固定 chunk 合成波形，则调度器的对齐长度天然落在 chunk 边界上，填充浪费最小；若上游是 RVQ 分层码本渐进解码、每层产出节奏不同，调度器就必须把“当前 chunk”定义为跨层的最小公倍节奏，否则批内会出现部分请求等层、部分请求空转。这里的系统代价是显存带宽：跨层对齐意味着同一 batch 内要同时驻留多层的中间激活，带宽占用随层数线性上升，而算力利用率未必同比例提升。工程判断是——当层数少（粗粒度码本）时优先跨层对齐换吞吐；层数多时改为按层分批，牺牲少量首包延迟换带宽。</p>\n<p>与投机解码的接口则相反：投机解码的 draft 与 verify 是两个不同粒度的前向，批调度若把 draft 与 verify 混在同一 batch，会让 verify 步被 draft 的短 chunk 拖慢。可行做法是把 draft 批与 verify 批分开调度，用同一优先级函数但独立 batch 槽位，verify 批享有更高的 $\\alpha$ 权重。代价是两套状态池并存，显存碎片风险叠加；这正是失败模式里“长对话累积后触发 OOM 或强制驱逐”的高发场景。因此在同时启用投机与连续批时，必须给状态缓存设硬上限并按请求生命周期回收，而不是等碎片累积到驱逐阈值才动作。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-51\">五十一 · 与分离式预填/解码及并行通信的耦合</h3>\n<p>当部署形态走向分离式预填/解码（prefill 与 decode 分卡或分池），批调度的选择维度要多加一个“跨池传输成本”。预填池产出的是 KV 与卷积状态，解码池消费它们；若调度器在 chunk 级连续批里频繁增删请求，跨池状态迁移的次数随之上升，NVLink 5 上的传输虽然带宽充裕，但每次迁移的固定开销会吃掉 chunk 变小带来的调度收益。适用条件是：chunk 大小要大于“一次状态迁移开销折算的等效计算时间”，否则连续批的收益被通信抵消。定性地说，chunk 越小、迁移越频繁，分离式部署越不划算；此时应回到单机多卡、状态本地管理的形态。</p>\n<p>并行与通信维度还影响抢占策略：在 NVL72 这类机架级域内，跨卡重算一个被抢占的 chunk 需要重新拉取该请求的历史 KV，通信量与该请求已服务 chunk 数成正比。于是抢占的代价不是常数，而是随 $n^{\\mathrm{served}}_r$ 增长。这解释了为什么长请求在持续过载下容易被饿死——每次重算的边际成本越来越高，调度器理性地选择不再救它。缓解手段是给长请求设“重算预算”，超过预算后不再抢占、改为排队等待，用可控的排队延迟换掉不可控的重算抖动。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-52\">五十二 · 适用条件与不适用边界</h3>\n<p>把族内选择收敛成几条硬判据。第一，长度方差：若请求音频时长的 P95/P50 比值接近 1，静态批的对齐浪费最小、状态管理最简单，不应引入 chunk 级连续批的碎片开销。第二，SLO 结构：首包延迟为硬约束、长尾吞吐为软目标时，动态 chunk 连续批是默认解；若两级 SLO 都硬，则必须上抢占批并接受尾延迟抖动，同时用重算预算封顶。第三，显存余量：每请求独立状态池的碎片率随并发请求数上升，当状态缓存容量逼近上限时，连续批的规模上限被显存而非算力锁定，此时增大 batch 只会推高驱逐概率，应改为限制单 batch 请求数并缩短 chunk。第四，数值格式：调度层不改变量化精度栈，NVFP4/FP8 的选择由算子层决定，调度器只需保证对齐后的 batch 形状落在 tcgen05 与 TMEM 友好的尺寸上，避免因填充导致的非对齐形状触发低效路径。</p>\n<p>不适用边界同样清晰：请求到达极度稀疏、并发长期低于 batch 下限时，连续批的调度与状态切换开销占比过高，不如退化为单请求直通；请求长度虽方差大但 SLO 极宽松时，静态批加排队即可，连续批的复杂度换不来可观测收益。最后一条工程判断落在 chunk 大小与 batch 上限的联合标定上——这两个参数共同决定对齐浪费、抢占重算量与首包延迟三者的平衡点，任何单独调其中一个都会把代价转移到另外两个上，因此必须作为一组参数在目标负载配方下标定，而不是分别取各自的最优值。</p>\n\n<h3 id=\"alg-stream-batch-scheduler-sec-53\">五十三 · 同族调度器的分岔口：何时该用 chunk 级连续批处理，何时该退回去</h3>\n<p>把本方案放进同族算法谱系里看，真正的分界线不在“是否连续批处理”，而在三个可判定的量：请求长度方差、首包 SLO 的松紧、以及状态缓存的可回收性。静态批一次成型、等最慢请求，等价于把整批的完成时间绑定到 $\\max_i L_{\\text{first},i}$，长度方差一大，短请求就被长请求拖住，首包抖动直接由批内最长者决定；而 chunk 级连续批处理每步可增删请求，新请求插入空槽，首包延迟不再被同批长请求拖累。判据可以写成一个准入条件：当 $\\mathrm{Var}(T_{\\text{audio}})$ 大到使静态批的槽位利用率显著低于 chunk 级拼批的有效占用，且首包 SLO 是硬约束时，才值得付出状态管理与对齐开销。反过来，若请求长度高度同质、SLO 宽松，静态批的对齐浪费最小、状态管理最简，本方案每步调度与按请求路由的固定开销反而成为纯亏损。同族里还有一类“按请求整段调度”的变体，它省掉 chunk 边界对齐但丧失抢占能力，在过载下只能整体排队，属于本方案在 SLO 极硬时的退化形态。</p>\n<p>决策要看系统代价落在哪一侧。本方案的代价结构是：每请求独立卷积/KV 状态带来显存碎片，batch 内长度对齐浪费算力，优先级抢占导致已分配 chunk 重算。三者随 batch 上限与 chunk 大小联动——chunk 过大，首包延迟上升，因为首个 chunk 的前向本身变长；chunk 过小，调度与状态切换开销占比过高，$\\text{RTF}$ 被固定开销吃掉。因此选型时应把 chunk 大小当作与 batch 上限联合求解的变量，而不是独立超参。用优先级式 $p_r = \\alpha\\cdot \\frac{1}{\\mathrm{SLO}_r} + \\beta\\cdot n^{\\mathrm{served}}_r$ 做抢占决策时，$\\beta$ 调大能防长请求饿死，但会推高短请求的首包尾延迟；$\\alpha$ 调大则相反，过载时保首包、牺牲长尾吞吐。这个权衡在两级 SLO（首包硬约束、长尾软目标）下是可接受的，但若业务把长尾吞吐也当硬指标，本方案就不再是正确选择，应转向能保证公平性的轮转式拼批。</p>\n<p>失效条件的识别比选型更重要。第一类是显存碎片累积：长对话下每请求状态缓存持续占用，碎片化到无法分配新槽位时触发 OOM 或强制驱逐，吞吐骤降；此时即便 RTF 仍小于 1，服务已不可用，监控必须把“可分配槽位数”而非仅 RTF 作为一级指标。第二类是持续过载下的饥饿：抢占重算放大尾延迟抖动，长请求在反复被抢占中推进极慢，形成事实上的饿死；缓解手段是限制单 batch 请求数与 chunk 上限，并对抢占导致的已分配 chunk 做重算补偿。第三类是对齐浪费：批内长度对齐到 chunk 边界虽减少填充，但当 batch 内 chunk 长度分布离散度高时，对齐后有效算力占比下降，此时应缩小 batch 上限而非加大 chunk。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选 chunk 级连续批处理</th><th>选静态批/整段调度</th></tr></thead><tbody><tr><td>请求长度方差</td><td>大，短长请求混流</td><td>小，长度同质</td></tr><tr><td>首包 SLO</td><td>硬约束，需抢占保首包</td><td>宽松，可整体排队</td></tr><tr><td>状态缓存</td><td>可按请求生命周期回收、分池</td><td>可整批一次性释放</td></tr><tr><td>过载策略</td><td>保首包、牺牲长尾吞吐</td><td>公平排队、整体降速</td></tr><tr><td>主要风险</td><td>碎片 OOM、抢占重算抖动</td><td>槽位利用率低、首包被拖</td></tr></tbody></table>\n<p>工程判断可以收敛成一句可执行的话：先用离线回放测出目标负载下静态批的槽位利用率与首包 P99，若静态批已能满足硬 SLO，就不要引入 chunk 级调度；只有当静态批的首包 P99 被批内最长请求顶穿、且状态缓存能被分池回收时，才切换到本方案，并把 batch 上限与 chunk 大小作为一对联合调参量、以可分配槽位数作为 OOM 前的一级熔断信号。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 批调度与实时率 SLO</td></tr><tr><td>解决什么</td><td>流式 TTS/语音对话服务中请求到达时间与音频长度差异大，静态批处理导致首包延迟抖动与 GPU 空转，难以同时满足 S…</td></tr><tr><td>一句话机制</td><td>以 chunk 为调度粒度做连续批处理：把不同请求的当前 chunk 拼成一批做前向，按 SLO 优先级与剩余 tok…</td></tr><tr><td>代价与失效</td><td>每请求独立卷积/KV 状态带来显存碎片，batch 内长度对齐浪费算力；优先级抢占会导致已分配 chunk 重算，增加尾延迟抖动</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-stream-batch-scheduler · 共 8 个片段</p>\n";break;}}})();
